export type GenCategory = 'LCG & MLCG' | 'Shift Register' | 'Modern & Quality' | 'Chaotic' | 'Classical';

export interface AlgoDef {
  id: string;
  name: string;
  category: GenCategory;
  desc: string;
  wiki: string;
}

export interface LfsrPreset {
  name: string;
  tap: string;
  desc: string;
}

export interface TestResult {
  name: string;
  score: number;
  displayValue?: string;
  status: 'PASS' | 'FAIL' | 'SUSPECT';
  desc: string;
}

export interface Candidate {
  algorithm: string;
  confidence: number;
  parameters: string;
  explanation: string;
}

export interface AnalysisResult {
  candidates: Candidate[];
  nextValues: number[];
}

import { GoogleGenAI, SchemaType, Type } from '@google/genai';
import { AnalysisResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeSequence = async (sequence: number[]): Promise<AnalysisResult> => {
  if (sequence.length < 3) {
    throw new Error("Provide at least 3 numbers for analysis.");
  }

  const prompt = `
    You are an expert Cryptanalyst and Mathematician specializing in PRNG reverse-engineering.

    INPUT SEQUENCE: [${sequence.join(', ')}]

    ### PRIMARY OBJECTIVE
    Identify the exact generator algorithm and RECOVER THE EXACT PARAMETERS (multipliers, moduli, seeds, taps, chaos rates) used.

    ### ANALYSIS INSTRUCTIONS
    1. **Parameter Solving (CRITICAL):**
       - **LCG (Linear Congruential):** Attempt to solve the system of linear equations $X_{n+1} = (a X_n + c) \\pmod m$. Determine 'a', 'c', and 'm'. Check if these match known standards (e.g., Numerical Recipes: a=1664525, c=1013904223; Borland: a=22695477; glibc: a=1103515245).
       - **Chaotic Maps:** For floats, solve for the control parameter (e.g., Logistic Map $r = X_{n+1} / (X_n(1-X_n))$). Check for precision artifacts.
       - **LFSR/Shift:** Analyze bitwise patterns. Check for common feedback polynomials.

    2. **Algorithm Classification:**
       Consider the following extensive knowledge base:

       **Linear & Modular:**
       - LCGs (Standard, Truncated), MLCGs (Lehmer), Combined LCGs (Wichmann-Hill).
       - Inverse Congruential, Hull-Dobell compliant params.

       **Bitwise & Shift Register:**
       - Xorshift (32, 64, 128, 1024), Xoroshiro (128+, 256+), XORShift*.
       - LFSR (Galois/Fibonacci), Tausworthe (Taus88), WELL.
       - Mersenne Twister (MT19937), SFMT.

       **Chaotic & Nonlinear:**
       - Logistic Map ($rx(1-x)$), Tent Map, Sine Map, Bernoulli Map.
       - Hénon Map, Ikeda Map, Lorenz/Rössler Attractors (sampled).

       **Modern & Fast:**
       - PCG Family (Permuted Congruential), SplitMix64.
       - SFC32, Mulberry32, WyRand.

       **Historical/Other:**
       - Middle Square, Lagged Fibonacci, Linear Feedback.
       - Digits of Pi/e/Phi, Prime sequences.

    3. **Output Requirements:**
       - Provide the top 3 candidates.
       - **Parameters Field:** MUST contain the recovered mathematical constants (e.g., "a=1664525, c=1013904223, m=2^32"). Do not just say "Standard LCG".
       - **Explanation:** Show the reasoning or mathematical check that confirmed the parameters.

    4. **Prediction:**
       - Calculate the NEXT 3 numbers in the sequence using the recovered parameters of the #1 candidate.
  `;

  const schema: SchemaType = {
    type: Type.OBJECT,
    properties: {
      candidates: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            algorithm: { type: Type.STRING, description: "Specific name of the algorithm (e.g., 'LCG (Numerical Recipes)')" },
            confidence: { type: Type.INTEGER, description: "Confidence score (0-100)" },
            parameters: { type: Type.STRING, description: "Exact recovered parameters (e.g., 'a=1664525, c=1013904223, m=2^32')" },
            explanation: { type: Type.STRING, description: "Mathematical derivation or reasoning for the match" }
          },
          required: ["algorithm", "confidence", "parameters", "explanation"]
        },
        description: "Top 3 potential algorithm matches with recovered parameters"
      },
      nextValues: { 
        type: Type.ARRAY, 
        items: { type: Type.NUMBER },
        description: "The next 3 predicted numbers"
      }
    },
    required: ["candidates", "nextValues"]
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: schema,
        temperature: 0.1
      }
    });

    return JSON.parse(response.text) as AnalysisResult;
  } catch (error) {
    console.error('Gemini Analysis Error:', error);
    throw error;
  }
};

import { TestResult } from '../types';

export interface GeneratorParams {
  a?: number;
  c?: number;
  m?: number;
  seed?: number;
  seed2?: number;
  seed3?: number;
  seed4?: number;
  stringSeed?: string;
  hexTap?: string;
  fibSeed1?: number;
  fibSeed2?: number;
  floatSeed?: number;
  paramR?: number; // r or mu
  paramA?: number;
  paramB?: number;
  paramC?: number;
  paramDt?: number;
}

export function generateInternalSequence(mode: string, params: GeneratorParams, limit: number): number[] {
  const result: number[] = [];

  // Destructure with defaults to avoid null checks everywhere
  const {
    a: aVal = 0, c: cVal = 0, m: mVal = 1,
    seed: seedVal = 0, seed2: seedVal2 = 0, seed3: seedVal3 = 0, seed4: seedVal4 = 0,
    hexTap = '', stringSeed = '',
    fibSeed1: f1Val = 0, fibSeed2: f2Val = 0,
    floatSeed: floatSeedVal = 0.5,
    paramR: pR = 0, paramA: pA = 0, paramB: pB = 0, paramC: pC = 0, paramDt: pDt = 0
  } = params;

  try {
    if (['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn'].includes(mode)) {
        let current = seedVal;
        for (let i = 0; i < limit; i++) {
          result.push(current);
          const safeM = mVal === 0 ? 1 : mVal;
          const next = (BigInt(aVal) * BigInt(current) + BigInt(cVal)) % BigInt(safeM);
          current = Number(next);
        }
    }
    else if (mode === 'tausworthe') {
        let s1 = seedVal, s2 = seedVal2, s3 = seedVal3;
        for(let i=0; i<limit; i++) {
           const b1 = (((s1 << 13) ^ s1) >>> 19);
           s1 = (((s1 & 0xFFFFFFFE) << 12) ^ b1);
           const b2 = (((s2 << 2) ^ s2) >>> 25);
           s2 = (((s2 & 0xFFFFFFF8) << 4) ^ b2);
           const b3 = (((s3 << 3) ^ s3) >>> 11);
           s3 = (((s3 & 0xFFFFFFF0) << 17) ^ b3);
           result.push((s1 ^ s2 ^ s3) >>> 0);
        }
    }
    else if (mode === 'lfsr8') {
       let lfsr = seedVal & 0xFF;
       const tap = parseInt(hexTap || '1D', 16);
       for(let i=0; i<limit; i++) {
          result.push(lfsr);
          const lsb = lfsr & 1;
          lfsr >>= 1;
          if (lsb) lfsr ^= tap;
       }
    }
    else if (mode === 'lfsr' || mode === 'lfsr32') {
       let lfsr = seedVal;
       const tapStr = hexTap || (mode === 'lfsr' ? 'B400' : '80200003');
       const tap = parseInt(tapStr, 16);
       for(let i=0; i<limit; i++) {
          result.push(lfsr >>> 0);
          const lsb = lfsr & 1;
          lfsr >>>= 1;
          if (lsb) lfsr ^= tap;
       }
    }
    else if (mode === 'lfsr64') {
       let lfsr = BigInt(stringSeed || "12345");
       const tapStr = hexTap || "D800000000000000";
       const tap = BigInt("0x" + tapStr);
       for(let i=0; i<limit; i++) {
          result.push(Number(lfsr & 0xFFFFFFFFn));
          const lsb = lfsr & 1n;
          lfsr >>= 1n;
          if (lsb) lfsr ^= tap;
       }
    }
    else if (mode === 'xorshift') {
        let x = seedVal || 123456789;
        for(let i=0; i<limit; i++) {
           x ^= x << 13;
           x ^= x >> 17;
           x ^= x << 5;
           result.push(x >>> 0);
        }
    }
    else if (mode === 'xorshift1024') {
        let z = BigInt(seedVal || 123456789);
        const s = new BigUint64Array(16);
        for(let i=0; i<16; i++) {
           z = (z + 0x9e3779b97f4a7c15n) & 0xFFFFFFFFFFFFFFFFn;
           let x = z;
           x = ((x ^ (x >> 30n)) * 0xbf58476d1ce4e5b9n) & 0xFFFFFFFFFFFFFFFFn;
           x = ((x ^ (x >> 27n)) * 0x94d049bb133111ebn) & 0xFFFFFFFFFFFFFFFFn;
           s[i] = (x ^ (x >> 31n)) & 0xFFFFFFFFFFFFFFFFn;
        }
        let p = 0;
        for(let i=0; i<limit; i++) {
           const s0 = s[p];
           p = (p + 1) & 15;
           let s1 = s[p];
           s1 ^= (s1 << 31n) & 0xFFFFFFFFFFFFFFFFn; 
           s[p] = (s1 ^ s0 ^ (s1 >> 11n) ^ (s0 >> 30n)) & 0xFFFFFFFFFFFFFFFFn;
           const val = (s[p] * 1181783497276652981n) & 0xFFFFFFFFFFFFFFFFn;
           result.push(Number(val & 0xFFFFFFFFn));
        }
    }
    else if (mode === 'splitmix') {
        let x = BigInt(seedVal || 123456789);
        for(let i=0; i<limit; i++) {
           x = (x + BigInt("0x9E3779B97F4A7C15")) & 0xFFFFFFFFFFFFFFFFn;
           let z = x;
           z = (z ^ (z >> 30n)) * BigInt("0xBF58476D1CE4E5B9");
           z = (z ^ (z >> 27n)) * BigInt("0x94D049BB133111EB");
           z = z ^ (z >> 31n);
           result.push(Number(z & 0xFFFFFFFFn));
        }
    }
    else if (mode === 'mulberry') {
        let state = seedVal || 12345;
        for(let i=0; i<limit; i++) {
           state = (state + 0x6D2B79F5) | 0;
           let t = Math.imul(state ^ (state >>> 15), 1 | state);
           t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
           result.push((t ^ (t >>> 14)) >>> 0);
        }
    }
    else if (mode === 'henon') {
        let x = floatSeedVal;
        let y = 0.1; 
        const a = pA || 1.4;
        const b = pB || 0.3;
        for(let i=0; i<limit; i++) {
            result.push(Number(x.toFixed(5)));
            const nextX = 1 - a * x * x + y;
            const nextY = b * x;
            x = nextX;
            y = nextY;
        }
    }
    else if (mode === 'ikeda') {
        let x = floatSeedVal;
        let y = 0.1;
        const u = pA || 0.9;
        for(let i=0; i<limit; i++) {
            result.push(Number(x.toFixed(5)));
            const t = 0.4 - 6 / (1 + x*x + y*y);
            const nextX = 1 + u * (x * Math.cos(t) - y * Math.sin(t));
            const nextY = u * (x * Math.sin(t) + y * Math.cos(t));
            x = nextX;
            y = nextY;
        }
    }
    else if (mode === 'lorenz') {
        let x = floatSeedVal;
        let y = 1.0, z = 1.0;
        const sigma = pA || 10.0;
        const rho = pB || 28.0;
        const beta = pC || 2.666;
        const dt = pDt || 0.01;

        for(let i=0; i<limit; i++) {
            result.push(Number(x.toFixed(4)));
            const dx = sigma * (y - x);
            const dy = x * (rho - z) - y;
            const dz = x * y - beta * z;
            x += dx * dt;
            y += dy * dt;
            z += dz * dt;
        }
    }
    else if (mode === 'rossler') {
        let x = floatSeedVal;
        let y = 1.0, z = 1.0;
        const a = pA || 0.2;
        const b = pB || 0.2;
        const c = pC || 5.7;
        const dt = pDt || 0.05;

        for(let i=0; i<limit; i++) {
            result.push(Number(x.toFixed(4)));
            const dx = -y - z;
            const dy = x + a * y;
            const dz = b + z * (x - c);
            x += dx * dt;
            y += dy * dt;
            z += dz * dt;
        }
    }
    else if (['logistic', 'tent'].includes(mode)) {
        let x = floatSeedVal;
        const param = pR || (mode === 'logistic' ? 3.99 : 1.99);
        for(let i=0; i<limit; i++) {
           result.push(Number(x.toFixed(5)));
           if (mode === 'logistic') x = param * x * (1 - x);
           else x = (x < 0.5) ? param * x : param * (1 - x);
        }
    }
    else if (mode === 'fib') {
        let f1 = f1Val;
        let f2 = f2Val;
        result.push(f1);
        if (limit > 1) result.push(f2);
        for(let i=2; i<limit; i++) {
           const next = f1 + f2;
           result.push(next);
           f1 = f2;
           f2 = next;
        }
    }
    else {
        // Fallback or PCG variants/others not fully implemented in snippet
        for(let i=0; i<limit; i++) {
           result.push(Math.floor(Math.random() * 100));
        }
    }
  } catch (e) {
    console.error(e);
  }

  return result;
}

export function performChiSquared(seq: number[]) {
  if (!seq.length) return null;

  const bins = 10;
  const observed = new Array(bins).fill(0);
  const isFloat = seq.some(n => !Number.isInteger(n));

  for (const val of seq) {
      let binIndex = 0;
      if (isFloat) {
          binIndex = Math.floor((Math.abs(val) % 1) * bins);
      } else {
          binIndex = Math.abs(val) % 10;
      }
      if (binIndex < 0) binIndex = 0;
      if (binIndex >= bins) binIndex = bins - 1;
      observed[binIndex]++;
  }

  const expected = seq.length / bins;
  let chiSq = 0;
  for (let i = 0; i < bins; i++) {
      chiSq += Math.pow(observed[i] - expected, 2) / expected;
  }

  return {
      score: chiSq,
      passed: chiSq < 16.92
  };
}

export function performDieharder(seq: number[]) {
  const n = seq.length;
  if (n < 10) return [];

  const results: TestResult[] = [];
  const min = Math.min(...seq);
  const max = Math.max(...seq);
  const range = (max - min) || 1;
  const normalized = seq.map(x => (x - min) / range);

  // 1. Monobit
  let ones = 0;
  for(const val of normalized) {
      if (val >= 0.5) ones++;
  }
  const prop = ones / n;
  const monobitScore = Math.abs((prop - 0.5) / (0.5 / Math.sqrt(n)));
  results.push({
      name: 'Monobit (Balance)',
      score: monobitScore,
      status: monobitScore < 1.96 ? 'PASS' : (monobitScore < 2.576 ? 'SUSPECT' : 'FAIL'),
      desc: 'Checks 0/1 balance. Z-score < 1.96 passes.'
  });

  // 2. Runs Test
  let runs = 1;
  for(let i=1; i<n; i++) {
      if ((seq[i] > seq[i-1]) !== (seq[i-1] > seq[i-2])) runs++;
  }
  const expectedRuns = (2 * n - 1) / 3;
  const runsVar = (16 * n - 29) / 90;
  const runsScore = Math.abs(runs - expectedRuns) / Math.sqrt(runsVar);
  results.push({
      name: 'Runs (Up/Down)',
      score: runsScore,
      status: runsScore < 2 ? 'PASS' : (runsScore < 3 ? 'SUSPECT' : 'FAIL'),
      desc: 'Checks sequential patterns. Z-score < 2 passes.'
  });

  // 3. Monte Carlo Pi
  let insideCircle = 0;
  const pairs = Math.floor(n / 2);
  for(let i=0; i<pairs; i++) {
      const x = normalized[2*i];
      const y = normalized[2*i+1];
      if (x*x + y*y <= 1) insideCircle++;
  }
  const piEst = 4 * (insideCircle / pairs);
  const piError = Math.abs(Math.PI - piEst);
  const piScore = (piError / Math.PI) * 100;
  results.push({
      name: 'Monte Carlo Pi',
      score: piScore,
      displayValue: `π ≈ ${piEst.toFixed(4)}`,
      status: piScore < 2.0 ? 'PASS' : (piScore < 5.0 ? 'SUSPECT' : 'FAIL'),
      desc: `Geometric test. Est: ${piEst.toFixed(4)}. Err: ${piScore.toFixed(2)}%`
  });

  // 4. Autocorrelation
  const mean = normalized.reduce((a,b) => a+b, 0) / n;
  let num = 0;
  let den = 0;
  for(let i=0; i<n-1; i++) {
      num += (normalized[i] - mean) * (normalized[i+1] - mean);
      den += Math.pow(normalized[i] - mean, 2);
  }
  const correlation = den === 0 ? 1 : num / den;
  const confInterval = 1.96 / Math.sqrt(n);
  const absCorr = Math.abs(correlation);
  results.push({
      name: 'Autocorrelation',
      score: absCorr,
      status: absCorr < confInterval ? 'PASS' : (absCorr < confInterval * 1.5 ? 'SUSPECT' : 'FAIL'),
      desc: `Lag-1 correlation: ${correlation.toFixed(4)}. Ideal: 0.`
  });

  return results;
}

import React, { useEffect, useRef } from 'react';

const MatrixRain: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let intervalId: NodeJS.Timeout;

    const initMatrix = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;

      const columns = Math.floor(canvas.width / 20);
      const drops: number[] = new Array(columns).fill(1);
      const chars = '0123456789ABCDEF';

      if (intervalId) clearInterval(intervalId);

      intervalId = setInterval(() => {
        ctx.fillStyle = 'rgba(15, 23, 42, 0.05)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = '#0ea5e9';
        ctx.font = '15px monospace';

        for (let i = 0; i < drops.length; i++) {
          const text = chars.charAt(Math.floor(Math.random() * chars.length));
          ctx.fillText(text, i * 20, drops[i] * 20);

          if (drops[i] * 20 > canvas.height && Math.random() > 0.975) {
            drops[i] = 0;
          }
          drops[i]++;
        }
      }, 50);
    };

    initMatrix();
    window.addEventListener('resize', initMatrix);

    return () => {
      clearInterval(intervalId);
      window.removeEventListener('resize', initMatrix);
    };
  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed top-0 left-0 w-full h-full pointer-events-none opacity-20 z-0"
    />
  );
};

export default MatrixRain;

import React, { useState } from 'react';
import { analyzeSequence } from '../services/geminiService';
import { AnalysisResult } from '../types';

const Analyzer: React.FC = () => {
  const [inputSequence, setInputSequence] = useState('');
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleAnalyze = async () => {
    const rawInput = inputSequence.trim();
    if (!rawInput) return;

    const sequence = rawInput.split(',')
      .map(s => parseFloat(s.trim()))
      .filter(n => !isNaN(n));

    if (sequence.length < 3) {
      setError("Please enter at least 3 valid numbers.");
      return;
    }

    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
      const analysis = await analyzeSequence(sequence);
      setResult(analysis);
    } catch (err) {
      setError("Analysis failed. Please try again or check your API key.");
    } finally {
      setIsLoading(false);
    }
  };

  const loadDemo = (type: 'lcg' | 'fib') => {
    if (type === 'lcg') {
      setInputSequence("1, 8, 11, 10, 5, 12");
    } else if (type === 'fib') {
      setInputSequence("0, 1, 1, 2, 3, 5, 8, 13, 21");
    }
  };

  return (
    <div className="space-y-6">
      <div className="glass-panel p-6 rounded-xl border-l-4 border-cyan-500 shadow-lg">
        <h2 className="text-xl font-bold text-white mb-4 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path stroke-linecap="round" stroke-linejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          Sequence Input
        </h2>

        <p className="text-slate-400 mb-4 text-sm">
          Enter a sequence of numbers separated by commas. The AI will attempt to reverse-engineer the generator.
        </p>

        <div className="flex gap-2 mb-4">
          <input 
            type="text" 
            value={inputSequence}
            onChange={(e) => setInputSequence(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAnalyze()}
            placeholder="e.g., 3, 10, 31, 94..." 
            className="flex-1 bg-slate-800 border border-slate-700 text-white px-4 py-3 rounded-lg focus:outline-none focus:border-cyan-500 font-mono transition-colors"
          />
          <button 
            onClick={handleAnalyze} 
            disabled={isLoading}
            className="bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-3 px-6 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center shadow-lg shadow-cyan-900/20">
            {isLoading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Cracking...
              </>
            ) : (
              'Analyze'
            )}
          </button>
        </div>

        <div className="flex gap-2">
           <button onClick={() => loadDemo('lcg')} className="text-xs bg-slate-700 hover:bg-slate-600 text-cyan-300 px-3 py-1 rounded transition-colors">
             Load LCG Demo
           </button>
           <button onClick={() => loadDemo('fib')} className="text-xs bg-slate-700 hover:bg-slate-600 text-cyan-300 px-3 py-1 rounded transition-colors">
             Load Fibonacci Demo
           </button>
        </div>

        {error && (
          <div className="mt-4 p-3 bg-red-900/30 border border-red-800 text-red-300 rounded text-sm">
            {error}
          </div>
        )}
      </div>

      {result && (
        <div className="glass-panel p-6 rounded-xl border-t border-slate-700 animation-fade-in">

          <div className="flex justify-between items-center mb-6">
             <h3 className="text-2xl font-bold text-white">Analysis Report</h3>
             <span className="text-xs text-slate-500 border border-slate-700 px-2 py-1 rounded">Model: Gemini 2.5 Flash</span>
          </div>

          <h4 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4">Detected Algorithms</h4>
          <div className="grid grid-cols-1 gap-4 mb-6">
             {result.candidates.map((candidate, index) => (
                <div key={index} className={`bg-slate-800/50 p-4 rounded-lg border ${
                     candidate.confidence >= 80 ? 'border-emerald-500' :
                     candidate.confidence >= 50 ? 'border-yellow-500' :
                     'border-slate-600'
                   }`}>
                  <div className="flex justify-between items-start mb-2">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-lg font-bold text-white">{candidate.algorithm}</span>
                        {index === 0 && (
                          <span className="bg-emerald-900/50 text-emerald-400 text-xs px-2 py-0.5 rounded uppercase font-bold">Best Match</span>
                        )}
                      </div>
                      <p className="font-mono text-xs text-slate-400 mt-1">{candidate.parameters || 'No parameters detected'}</p>
                    </div>
                    <div className="flex flex-col items-end">
                       <span className={`text-2xl font-bold font-mono ${
                             candidate.confidence >= 80 ? 'text-emerald-400' :
                             candidate.confidence >= 50 ? 'text-yellow-400' :
                             'text-slate-400'
                           }`}>
                         {candidate.confidence}%
                       </span>
                       <span className="text-xs text-slate-500 uppercase">Confidence</span>
                    </div>
                  </div>
                  <p className="text-sm text-slate-300 border-t border-slate-700/50 pt-2 mt-2 leading-relaxed">
                    {candidate.explanation}
                  </p>
                </div>
             ))}
          </div>

          <div className="bg-slate-900/50 p-6 rounded-lg border border-slate-800">
            <h4 className="text-sm font-semibold text-cyan-400 uppercase tracking-wider mb-4 flex items-center">
              <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"></path></svg>
              Predicted Next Sequence
            </h4>
            <div className="flex gap-4">
              {result.nextValues.map((val, index) => (
                <div key={index} className="bg-slate-950 border border-cyan-900 text-cyan-300 font-mono text-2xl py-4 px-6 rounded-lg shadow-lg flex-1 text-center relative overflow-hidden group">
                    <span className="relative z-10">{val}</span>
                    <div className="absolute top-0 right-0 p-1">
                      <span className="text-[10px] text-slate-600">n+{index + 1}</span>
                    </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Analyzer;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { AlgoDef, GenCategory, LfsrPreset, TestResult } from '../types';
import { GeneratorParams, generateInternalSequence, performChiSquared, performDieharder } from '../utils/generatorUtils';

const categories: GenCategory[] = ['LCG & MLCG', 'Shift Register', 'Modern & Quality', 'Chaotic', 'Classical'];

const algorithms: AlgoDef[] = [
    { id: 'lcg', name: 'Custom LCG', category: 'LCG & MLCG', desc: 'The Linear Congruential Generator is the "Hello World" of PRNGs. Defined by the recurrence X = (aX + c) mod m.', wiki: 'https://en.wikipedia.org/wiki/Linear_congruential_generator' },
