    { id: 'minstd', name: 'MINSTD (MLCG)', category: 'LCG & MLCG', desc: 'Park & Miller (1988) "Minimum Standard".', wiki: 'https://en.wikipedia.org/wiki/Lehmer_random_number_generator' },
