    { id: 'tent', name: 'Tent Map', category: 'Chaotic', desc: 'Piecewise linear map on [0,1].', wiki: 'https://en.wikipedia.org/wiki/Tent_map' },
    { id: 'henon', name: 'Hénon Map', category: 'Chaotic', desc: 'Discrete-time dynamical system with strange attractors.', wiki: 'https://en.wikipedia.org/wiki/H%C3%A9non_map' },
