    { id: 'lorenz', name: 'Lorenz Attractor', category: 'Chaotic', desc: 'Atmospheric convection model (Butterfly effect).', wiki: 'https://en.wikipedia.org/wiki/Lorenz_system' },
    { id: 'rossler', name: 'Rössler Attractor', category: 'Chaotic', desc: 'Similar to Lorenz but simpler equations.', wiki: 'https://en.wikipedia.org/wiki/R%C3%B6ssler_attractor' },

    { id: 'fib', name: 'Fibonacci', category: 'Classical', desc: 'Predictable sequence: F(n) = F(n-1) + F(n-2).', wiki: 'https://en.wikipedia.org/wiki/Fibonacci_number' },
