                    <div className="absolute top-0 right-0 p-1">
                      <span className="text-[10px] text-slate-600">n+{index + 1}</span>
                    </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {history.length > 0 && (
        <div className="glass-panel p-6 rounded-xl border border-slate-700/50 animation-fade-in mt-6">
          <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">Recent Analyses</h4>
          <div className="space-y-2">
            {history.map((item, idx) => (
              <button
                key={idx}
                onClick={() => loadHistoryItem(item)}
                className="w-full text-left bg-slate-800/40 hover:bg-slate-800 p-3 rounded-lg border border-slate-700/50 transition-colors flex justify-between items-center group"
              >
                 <div className="overflow-hidden">
                    <p className="text-xs font-mono text-slate-300 truncate w-full mb-1">{item.input}</p>
                    <p className="text-[10px] text-cyan-500 font-bold">
                       {item.result.candidates[0].algorithm} <span className="text-slate-500 font-normal">({item.result.candidates[0].confidence}%)</span>
                    </p>
                 </div>
                 <div className="text-[10px] text-slate-600 group-hover:text-slate-400">
                    Load
                 </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Analyzer;

