        if (mode === 'logistic' || mode === 'tent') {
            ctx.fillStyle = 'rgba(168, 85, 247, 0.4)';
            const rMin = (mode === 'logistic') ? 2.0 : 1.0;
            const rMax = (mode === 'logistic') ? 4.0 : 2.0;

            for (let px = 0; px < width; px++) {
                const r = rMin + (px / width) * (rMax - rMin);
                let x = 0.5;
                // warmup
                for (let i = 0; i < 50; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                }
                // draw
                for (let i = 0; i < 30; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                    const py = height - (x * height);
                    ctx.fillRect(px, py, 1, 1);
                }
            }
            // Indicator
            const currentR = params.paramR ?? 0;
            if (currentR >= rMin && currentR <= rMax) {
                const lineX = ((currentR - rMin) / (rMax - rMin)) * width;
                ctx.strokeStyle = '#22d3ee';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(lineX, 0);
                ctx.lineTo(lineX, height);
                ctx.stroke();
            }
        } else if (mode === 'lorenz') {
             // Smoother Lorenz drawing
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.01;
             const a = params.paramA ?? 10, b = params.paramB ?? 28, c = params.paramC ?? 2.66;

             // Warmup
             for(let i=0; i<100; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 10, scaleY = 5, offX = width/2;

             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, height - (z * scaleY));

             // Increase iteration count for smoothness
             for(let i=0; i<10000; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;

                // Draw line for smoothness
                ctx.lineTo(offX + x * scaleX, height - (z * scaleY));
             }
             ctx.stroke();

        } else if (mode === 'rossler') {
             // Rössler drawing
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.05;
             const a = params.paramA ?? 0.2, b = params.paramB ?? 0.2, c = params.paramC ?? 5.7;

             // Warmup
             for(let i=0; i<100; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 8, scaleY = 8, offX = width/2, offY = height/2 + 50;
             ctx.strokeStyle = 'rgba(236, 72, 153, 0.4)';
             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, offY - (y * scaleY)); // Plot X vs Y

             for(let i=0; i<10000; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
                 ctx.lineTo(offX + x * scaleX, offY - (y * scaleY));
             }
             ctx.stroke();
        }
    }, [mode, activeCategory, params]);

    useEffect(() => {
        if (activeCategory === 'Chaotic') {
            const timer = setTimeout(drawChaos, 50);
            return () => clearTimeout(timer);
        }
    }, [drawChaos, activeCategory]);

    const handleGenerate = () => {
        if (hasErrors) return;
        const seq = generateInternalSequence(mode, params, count);
        setSequence(seq);
        setChiResult(null);
        setDieharderResults([]);
    };

    const handleStats = (type: 'chi' | 'full') => {
        // Generate larger sequence for tests
        const testSeq = generateInternalSequence(mode, params, Math.max(testLimit, 1000));
        if (type === 'chi') {
            setChiResult(performChiSquared(testSeq));
        } else {
            setDieharderResults(performDieharder(testSeq));
        }
    };

    const copyToClipboard = () => {
        navigator.clipboard.writeText(sequence.join(', '));
        setCopyStatus('Copied!');
        setTimeout(() => setCopyStatus('Copy'), 2000);
    };

    return (
        <div className="glass-panel p-6 rounded-xl border-t border-b border-purple-500/30 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-purple-600/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

            <div className="relative z-10">
                <h2 className="text-2xl font-black text-white mb-6 flex items-center tracking-tight">
