                            <>
                                <div><label className="block text-slate-400 text-xs font-bold mb-2">Seed 1</label><input type="number" value={params.seed} onChange={e => setParam('seed', parseInt(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                {['xoroshiro128plus', 'xorshift1024'].includes(mode) && (
