    { name: 'CCITT (1021)', tap: '1021', desc: 'Used in CRC-CCITT / X.25' },
    { name: 'Poly 0x002D', tap: '002D', desc: 'Maximal length (x^16 + x^15 + x^13 + x^4 + 1)' },
];
