    { name: 'Xilinx Standard', tap: '80200003', desc: 'Xilinx App Note 052' },
    { name: 'CRC-32 (04C11DB7)', tap: '04C11DB7', desc: 'Ethernet, ZIP, PNG checksum' },
    { name: 'Castagnoli (1EDC6F41)', tap: '1EDC6F41', desc: 'CRC32C (iSCSI, Btrfs, Ext4)' },
];
const lfsr64Presets: LfsrPreset[] = [
    { name: 'ISO 3309 (D8...)', tap: 'D800000000000000', desc: 'Standard primitive polynomial for 64-bit' },
    { name: 'ECMA-182 (C9...)', tap: 'C96C5795D7870F42', desc: 'Polynomial from ECMA-182 standard' },
];

const Playground: React.FC = () => {
    const [activeCategory, setActiveCategory] = useState<GenCategory>('LCG & MLCG');
    const [mode, setMode] = useState<string>('lcg');
    const [count, setCount] = useState(10);
    const [testLimit, setTestLimit] = useState(1000);
    const [showDetails, setShowDetails] = useState(false);

    const [params, setParams] = useState<GeneratorParams>({
        a: 1664525, c: 1013904223, m: 4294967296, seed: 12345,
        seed2: 54321, seed3: 9999, seed4: 10101,
        stringSeed: 'EntropyOracle', hexTap: 'B400',
        fibSeed1: 0, fibSeed2: 1,
        floatSeed: 0.5, paramR: 3.99, paramA: 1.4, paramB: 0.3, paramC: 2.66, paramDt: 0.01
    });

    const [sequence, setSequence] = useState<number[]>([]);
    const [chiResult, setChiResult] = useState<{score: number, passed: boolean} | null>(null);
    const [dieharderResults, setDieharderResults] = useState<TestResult[]>([]);
    const [copyStatus, setCopyStatus] = useState('Copy');

    const canvasRef = useRef<HTMLCanvasElement>(null);

    const currentAlgo = algorithms.find(a => a.id === mode);
    const filteredAlgorithms = algorithms.filter(a => a.category === activeCategory);

    // Enhanced Validation Logic
    const currentErrors = useMemo(() => {
        const errs: Record<string, string> = {};
        if (count <= 0) errs['count'] = "Count must be > 0";
        if (count > 50000) errs['count'] = "Max limit 50,000";

        // Seed Validation
        if (['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn', 'xorshift', 'splitmix', 'mulberry', 'mt19937'].includes(mode)) {
             if (params.seed === undefined || isNaN(params.seed) || !Number.isInteger(params.seed)) {
                 errs['seed'] = "Seed must be an integer";
             }
        }

        // Specific checks for generators that fail with 0 seed
        if (['xorshift', 'splitmix', 'mulberry'].includes(mode)) {
             if (params.seed === 0) errs['seed'] = "Seed cannot be 0";
        }

        if (['lcg', 'minstd', 'carbon'].includes(mode)) {
            if ((params.m || 0) <= 0) errs['m'] = "Modulus must be > 0";
            if ((params.a || 0) < 0) errs['a'] = "Multiplier must be >= 0";
        }

        if (mode.includes('lfsr') && !/^[0-9A-Fa-f]+$/.test(params.hexTap || '')) {
            errs['hexTap'] = "Invalid Hexadecimal";
        }

        if (mode === 'logistic' || mode === 'tent') {
            if ((params.paramR || 0) > 4.0) errs['paramR'] = "r should be <= 4.0";
            if ((params.paramR || 0) < 0) errs['paramR'] = "r must be >= 0";
            if ((params.floatSeed || 0) < 0 || (params.floatSeed || 0) > 1) errs['floatSeed'] = "X0 must be in [0, 1]";
        }

        // Chaos params validation
        if (['lorenz', 'rossler', 'ikeda', 'henon'].includes(mode)) {
             if ((params.paramDt || 0) <= 0) errs['paramDt'] = "dt must be > 0";
             if ((params.paramDt || 0) > 0.5) errs['paramDt'] = "dt too large for stability";
        }

        return errs;
    }, [mode, params, count]);

    const hasErrors = Object.keys(currentErrors).length > 0;

    const setParam = (key: keyof GeneratorParams, val: any) => {
        setParams(prev => ({ ...prev, [key]: val }));
    };

    const randomizeCurrent = () => {
        const arr = new Uint32Array(4);
        window.crypto.getRandomValues(arr);

        let newParams = { ...params };

        if (['lcg', 'minstd', 'mt19937'].includes(mode)) {
           newParams.seed = arr[0] || 12345;
        } else if (mode.includes('lfsr')) {
           newParams.seed = arr[0] || 1;
           if (mode === 'lfsr64') newParams.stringSeed = BigInt(arr[0] + arr[1]).toString();
        } else if (['logistic', 'tent', 'henon', 'lorenz', 'rossler'].includes(mode)) {
           newParams.floatSeed = parseFloat(Math.random().toFixed(5)) || 0.1;
        } else {
            newParams.seed = arr[0];
            newParams.seed2 = arr[1];
        }
        setParams(newParams);
    };

    const setDefaultParams = (id: string) => {
        let p: GeneratorParams = { ...params };
        if (id === 'lcg') { p.a=1664525; p.c=1013904223; p.m=4294967296; p.seed=12345; }
        if (id === 'randu') { p.a=65539; p.c=0; p.m=2147483648; p.seed=1; }
        if (id === 'logistic') { p.floatSeed=0.5; p.paramR=3.99; }
        if (id === 'lorenz') { p.floatSeed=0.1; p.paramA=10; p.paramB=28; p.paramC=2.66; p.paramDt=0.01; }
        if (id === 'rossler') { p.floatSeed=0.1; p.paramA=0.2; p.paramB=0.2; p.paramC=5.7; p.paramDt=0.05; }
        if (id === 'lfsr8') { p.seed=0x1F; p.hexTap='1D'; }
        if (id === 'xoroshiro128plus') { p.seed=123456; p.seed2=987654; }
        if (id === 'mt19937') { p.seed=5489; }
        setParams(p);
    };

    const handleModeChange = (id: string) => {
        setMode(id);
        setSequence([]);
        setChiResult(null);
        setDieharderResults([]);
        setShowDetails(false);
        setDefaultParams(id);
    };

    const handleCategoryChange = (cat: GenCategory) => {
        setActiveCategory(cat);
        const first = algorithms.find(a => a.category === cat);
        if (first) handleModeChange(first.id);
    };

    const drawChaos = useCallback(() => {
        if (activeCategory !== 'Chaotic') return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const width = canvas.width;
        const height = canvas.height;
        ctx.fillStyle = '#050b14';
        ctx.fillRect(0, 0, width, height);

        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(34, 211, 238, 0.4)';
        ctx.fillStyle = 'rgba(34, 211, 238, 0.6)';

        if (mode === 'logistic' || mode === 'tent') {
            ctx.fillStyle = 'rgba(168, 85, 247, 0.4)';
            const rMin = (mode === 'logistic') ? 2.0 : 1.0;
            const rMax = (mode === 'logistic') ? 4.0 : 2.0;

            for (let px = 0; px < width; px++) {
                const r = rMin + (px / width) * (rMax - rMin);
                let x = 0.5;
                // warmup
                for (let i = 0; i < 50; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                }
                // draw
                for (let i = 0; i < 30; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                    const py = height - (x * height);
                    ctx.fillRect(px, py, 1, 1);
                }
            }
            // Indicator
            const currentR = params.paramR ?? 0;
            if (currentR >= rMin && currentR <= rMax) {
                const lineX = ((currentR - rMin) / (rMax - rMin)) * width;
                ctx.strokeStyle = '#22d3ee';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(lineX, 0);
                ctx.lineTo(lineX, height);
                ctx.stroke();
            }
        } else if (mode === 'lorenz') {
             // Smoother Lorenz drawing
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.01;
             const a = params.paramA ?? 10, b = params.paramB ?? 28, c = params.paramC ?? 2.66;

             // Warmup
             for(let i=0; i<100; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 10, scaleY = 5, offX = width/2;

             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, height - (z * scaleY));

             // Increase iteration count for smoothness
             for(let i=0; i<10000; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;

                // Draw line for smoothness
                ctx.lineTo(offX + x * scaleX, height - (z * scaleY));
             }
             ctx.stroke();

        } else if (mode === 'rossler') {
             // Rössler drawing
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.05;
             const a = params.paramA ?? 0.2, b = params.paramB ?? 0.2, c = params.paramC ?? 5.7;

             // Warmup
             for(let i=0; i<100; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 8, scaleY = 8, offX = width/2, offY = height/2 + 50;
             ctx.strokeStyle = 'rgba(236, 72, 153, 0.4)';
             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, offY - (y * scaleY)); // Plot X vs Y

             for(let i=0; i<10000; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
                 ctx.lineTo(offX + x * scaleX, offY - (y * scaleY));
             }
             ctx.stroke();
        }
    }, [mode, activeCategory, params]);

    useEffect(() => {
        if (activeCategory === 'Chaotic') {
            const timer = setTimeout(drawChaos, 50);
            return () => clearTimeout(timer);
        }
    }, [drawChaos, activeCategory]);

    const handleGenerate = () => {
        if (hasErrors) return;
        const seq = generateInternalSequence(mode, params, count);
        setSequence(seq);
        setChiResult(null);
        setDieharderResults([]);
    };

    const handleStats = (type: 'chi' | 'full') => {
        // Generate larger sequence for tests
        const testSeq = generateInternalSequence(mode, params, Math.max(testLimit, 1000));
        if (type === 'chi') {
            setChiResult(performChiSquared(testSeq));
        } else {
            setDieharderResults(performDieharder(testSeq));
        }
    };

    const copyToClipboard = () => {
        navigator.clipboard.writeText(sequence.join(', '));
        setCopyStatus('Copied!');
        setTimeout(() => setCopyStatus('Copy'), 2000);
    };

    const renderChaosControls = () => {
        if (mode === 'lorenz' || mode === 'rossler') {
            return (
                <div className="absolute top-3 right-4 z-20 bg-slate-900/90 p-3 rounded-lg border border-slate-700/50 w-48 backdrop-blur-md shadow-xl">
                     <div className="space-y-3">
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1">
                                <span>DT (Step)</span>
                                <span>{params.paramDt}</span>
                            </label>
                            <input type="range" min="0.001" max="0.1" step="0.001" value={params.paramDt} onChange={(e) => setParam('paramDt', parseFloat(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1">
                                <span>{mode === 'lorenz' ? 'Sigma' : 'a'}</span>
                                <span>{params.paramA}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 50 : 1} step={mode === 'lorenz' ? 0.1 : 0.01} value={params.paramA} onChange={(e) => setParam('paramA', parseFloat(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1">
                                <span>{mode === 'lorenz' ? 'Rho' : 'b'}</span>
                                <span>{params.paramB}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 100 : 1} step={mode === 'lorenz' ? 0.1 : 0.01} value={params.paramB} onChange={(e) => setParam('paramB', parseFloat(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1">
                                <span>{mode === 'lorenz' ? 'Beta' : 'c'}</span>
                                <span>{params.paramC}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 10 : 20} step="0.01" value={params.paramC} onChange={(e) => setParam('paramC', parseFloat(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                     </div>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="glass-panel p-6 rounded-xl border-t border-b border-purple-500/30 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-purple-600/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

            <div className="relative z-10">
                <h2 className="text-2xl font-black text-white mb-6 flex items-center tracking-tight">
                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-pink-400">GENERATOR LAB</span>
                </h2>

                <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-700/50 pb-2">
                    {categories.map(cat => (
                        <button
                            key={cat}
                            onClick={() => handleCategoryChange(cat)}
                            className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-lg transition-all ${
                                activeCategory === cat ? 'bg-slate-800 text-purple-400 border border-purple-500/50' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50 border border-transparent'
                            }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 mb-8">
                    {filteredAlgorithms.map(algo => (
                        <button
                            key={algo.id}
                            onClick={() => handleModeChange(algo.id)}
                            className={`px-3 py-3 rounded-lg text-xs font-bold transition-all text-left border relative overflow-hidden group shadow-sm flex flex-col justify-center min-h-[3.5rem] ${
                                mode === algo.id ? 'bg-purple-600 border-purple-400 text-white shadow-purple-900/50' : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:border-purple-500/50 hover:text-slate-200'
                            }`}
                        >
                            <span className="relative z-10 truncate w-full">{algo.name}</span>
                            {mode === algo.id && <div className="absolute inset-0 bg-gradient-to-br from-purple-600 to-indigo-600 opacity-100 z-0"></div>}
                        </button>
                    ))}
                </div>

                {currentAlgo && (
                    <div className="bg-slate-900/60 border-l-4 border-cyan-500 p-5 rounded-r-lg mb-8 flex flex-col sm:flex-row justify-between items-start gap-4 shadow-inner relative">
                        <div className="flex-1">
                            <h3 className="text-white font-bold text-lg mb-2 flex flex-wrap items-center gap-2">
                                {currentAlgo.name}
                                <span className="px-2 py-0.5 rounded-full bg-slate-800 text-[10px] text-cyan-400 border border-slate-700 uppercase tracking-widest">{currentAlgo.category}</span>
                            </h3>
                            <p className="text-slate-300 text-sm leading-relaxed">{currentAlgo.desc}</p>

                            <button 
                                onClick={() => setShowDetails(!showDetails)}
                                className="mt-3 text-[10px] font-bold uppercase tracking-widest text-purple-400 hover:text-purple-300 flex items-center"
                            >
                                {showDetails ? 'Hide Details' : 'Show Key Characteristics'}
                                <svg className={`w-3 h-3 ml-1 transform transition-transform ${showDetails ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </button>
                        </div>
                        <a href={currentAlgo.wiki} target="_blank" rel="noopener noreferrer" className="flex-shrink-0 text-cyan-500 hover:text-cyan-300 transition-colors text-xs font-mono border border-cyan-900/50 bg-cyan-950/30 px-3 py-2 rounded hover:border-cyan-500">
                            Wiki
                        </a>

                        {showDetails && (
                            <div className="absolute top-full left-0 w-full mt-2 bg-slate-900 border border-slate-700 p-4 rounded-lg shadow-xl z-20 animation-fade-in text-left">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <h5 className="text-[10px] text-emerald-400 uppercase font-bold mb-2 border-b border-emerald-900/50 pb-1">Characteristics</h5>
                                        <ul className="list-disc list-inside text-xs text-slate-300 space-y-1">
                                            {currentAlgo.characteristics?.map((c, i) => <li key={i}>{c}</li>) || <li className="italic text-slate-500">No data available</li>}
                                        </ul>
                                    </div>
                                    <div>
                                        <h5 className="text-[10px] text-red-400 uppercase font-bold mb-2 border-b border-red-900/50 pb-1">Limitations</h5>
                                        <ul className="list-disc list-inside text-xs text-slate-300 space-y-1">
                                            {currentAlgo.limitations?.map((l, i) => <li key={i}>{l}</li>) || <li className="italic text-slate-500">No data available</li>}
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {activeCategory === 'Chaotic' && (
                    <div className="mb-8 relative bg-slate-950 rounded-xl border border-slate-800 p-1 overflow-hidden h-64">
                         <div className="absolute top-3 left-4 z-10 pointer-events-none">
                            <label className="text-xs font-bold text-purple-300 bg-slate-900/80 px-2 py-1 rounded backdrop-blur-sm border border-purple-500/20">
                                {mode === 'lorenz' ? 'Phase Space (X vs Z)' : mode === 'rossler' ? 'Phase Space (X vs Y)' : 'Visualization'}
                            </label>
                         </div>

                        {renderChaosControls()}

                        <canvas 
                            ref={canvasRef} 
                            width={800} 
                            height={250} 
                            className="w-full h-full rounded-lg bg-[#050b14] cursor-crosshair"
                            onClick={(e) => {
                                if (mode !== 'logistic' && mode !== 'tent') return;
                                const rect = e.currentTarget.getBoundingClientRect();
                                const x = e.clientX - rect.left;
                                const rMin = mode === 'logistic' ? 2.0 : 1.0;
                                const rMax = mode === 'logistic' ? 4.0 : 2.0;
                                setParam('paramR', parseFloat((rMin + (x/rect.width) * (rMax - rMin)).toFixed(4)));
                            }}
                        />
                    </div>
                )}

                <div className="bg-slate-800/30 rounded-xl p-8 border border-slate-700/50 mb-6">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-6 border-b border-slate-700/50 pb-2">Configuration Variables</h4>

                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-x-8 gap-y-10">
                        {/* LCG Inputs */}
                        {['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn'].includes(mode) && (
                            <>
                                <div className="col-span-1 md:col-span-4 flex justify-between">
                                    <label className="text-slate-400 font-bold text-xs uppercase">LCG Parameters</label>
                                    <button onClick={randomizeCurrent} className="text-cyan-400 text-xs uppercase font-bold hover:text-cyan-300">Randomize All</button>
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Multiplier (a)</label>
                                    <input type="number" value={params.a} onChange={e => setParam('a', parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['a'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['a'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['a']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Increment (c)</label>
                                    <input type="number" value={params.c} onChange={e => setParam('c', parseInt(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" />
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Modulus (m)</label>
                                    <input type="number" value={params.m} onChange={e => setParam('m', parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['m'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['m'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['m']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Seed</label>
                                    <input type="number" value={params.seed} onChange={e => setParam('seed', parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                </div>
                            </>
                        )}

                        {/* Chaos Inputs */}
                        {(['logistic', 'tent', 'lorenz', 'rossler', 'ikeda', 'henon'].includes(mode)) && (
                            <>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Initial X</label>
                                    <input type="number" step="0.01" value={params.floatSeed} onChange={e => setParam('floatSeed', parseFloat(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['floatSeed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['floatSeed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['floatSeed']}</span>}
                                </div>
                                {['logistic', 'tent'].includes(mode) && (
                                    <div>
                                        <label className="block text-slate-400 text-xs font-bold mb-2">Rate (r/mu)</label>
                                        <input type="number" step="0.01" value={params.paramR} onChange={e => setParam('paramR', parseFloat(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['paramR'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                        {currentErrors['paramR'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['paramR']}</span>}
                                    </div>
                                )}
                                {['lorenz', 'rossler'].includes(mode) && (
                                    <>
                                        <div>
                                            <label className="block text-slate-400 text-xs font-bold mb-2">Time Step (dt)</label>
                                            <input type="number" step="0.001" value={params.paramDt} onChange={e => setParam('paramDt', parseFloat(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['paramDt'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                            {currentErrors['paramDt'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['paramDt']}</span>}
                                        </div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param A (Sigma/a)</label><input type="number" step="0.1" value={params.paramA} onChange={e => setParam('paramA', parseFloat(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param B (Rho/b)</label><input type="number" step="0.1" value={params.paramB} onChange={e => setParam('paramB', parseFloat(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param C (Beta/c)</label><input type="number" step="0.1" value={params.paramC} onChange={e => setParam('paramC', parseFloat(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                    </>
                                )}
                            </>
                        )}

                        {/* LFSR 8/16/32 */}
                        {(mode === 'lfsr8' || mode === 'lfsr' || mode === 'lfsr32' || mode === 'lfsr64') && (
                             <>
                                {mode !== 'lfsr64' ? (
                                    <div>
                                        <label className="block text-slate-400 text-xs font-bold mb-2">Seed (Int)</label>
                                        <input type="number" value={params.seed} onChange={e => setParam('seed', parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                        {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                    </div>
                                ) : (
                                    <div><label className="block text-slate-400 text-xs font-bold mb-2">Seed (BigInt String)</label><input type="text" value={params.stringSeed} onChange={e => setParam('stringSeed', e.target.value)} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                )}

                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Tap (Hex)</label>
                                    <input type="text" value={params.hexTap} onChange={e => setParam('hexTap', e.target.value)} className={`w-full bg-slate-900/50 border ${currentErrors['hexTap'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['hexTap'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['hexTap']}</span>}
                                    <div className="mt-2 text-[10px] text-slate-500 flex flex-wrap gap-2">
                                        <span className="w-full font-bold opacity-50">PRESETS:</span>
                                        {(mode === 'lfsr8' ? lfsr8Presets : mode === 'lfsr' ? lfsr16Presets : mode === 'lfsr32' ? lfsr32Presets : lfsr64Presets).map(p => (
                                            <button key={p.name} onClick={() => setParam('hexTap', p.tap)} className="text-purple-400 hover:text-purple-300 underline" title={p.desc}>{p.name}</button>
                                        ))}
                                    </div>
                                </div>
                             </>
                        )}

                        {/* Xorshift / Splitmix / Mulberry / Xoroshiro / MT19937 */}
                        {['xorshift', 'xorshift1024', 'xoroshiro128plus', 'splitmix', 'mulberry', 'mt19937'].includes(mode) && (
                            <>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Seed 1</label>
                                    <input type="number" value={params.seed} onChange={e => setParam('seed', parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs`} />
                                    {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                </div>
                                {['xoroshiro128plus', 'xorshift1024'].includes(mode) && (
                                     <div><label className="block text-slate-400 text-xs font-bold mb-2">Seed 2</label><input type="number" value={params.seed2} onChange={e => setParam('seed2', parseInt(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" /></div>
                                )}
                            </>
                        )}

                         {/* Fallback for others not explicitly handled above */}
                        {!['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn', 'logistic', 'tent', 'lorenz', 'rossler', 'ikeda', 'henon', 'lfsr8', 'lfsr', 'lfsr32', 'lfsr64', 'xorshift', 'xorshift1024', 'xoroshiro128plus', 'splitmix', 'mulberry', 'mt19937'].includes(mode) && !mode.includes('lfsr') && (
                             <div>
                                <label className="block text-slate-400 text-xs font-bold mb-2">Seed</label>
                                <input type="number" value={params.seed} onChange={e => setParam('seed', parseInt(e.target.value))} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs" />
                             </div>
                        )}

                        <div className="col-span-1 sm:col-span-2 xl:col-span-4 border-t border-slate-700/50 pt-8 mt-6">
                            <div className="flex flex-col sm:flex-row items-center gap-6 bg-slate-900/40 p-4 rounded-lg border border-slate-800">
                                <div className="w-full flex-1">
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Display Length (3 - 500)</label>
                                    <input type="range" min="3" max="500" value={count} onChange={e => setCount(parseInt(e.target.value))} className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                                </div>
                                <div className="w-full sm:w-24">
                                    <input type="number" min="3" max="500" value={count} onChange={e => setCount(parseInt(e.target.value))} className={`w-full bg-slate-900/50 border ${currentErrors['count'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-center font-bold text-lg`} />
                                    {currentErrors['count'] && <span className="text-red-500 text-[10px] block mt-1 text-center">{currentErrors['count']}</span>}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6">
                    <button onClick={handleGenerate} className="w-full sm:w-auto group relative bg-purple-600 hover:bg-purple-500 text-white font-bold py-3 px-8 rounded-lg transition-all shadow-lg shadow-purple-900/30 overflow-hidden">
                        Generate Sequence
                    </button>
                </div>

                {sequence.length > 0 && (
                    <div className="bg-slate-900/80 p-5 rounded-lg border border-slate-700 shadow-xl relative group animation-fade-in">
                        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center mb-4 pb-2 border-b border-slate-800 gap-4">
                            <h3 className="text-xs text-purple-400 uppercase tracking-widest font-bold flex items-center">
                                <span className="w-2 h-2 rounded-full bg-purple-500 mr-2"></span>
                                Output Sequence ({sequence.length})
                            </h3>
                            <div className="flex flex-col sm:flex-row gap-4 items-center w-full xl:w-auto">
                                <div className="flex items-center gap-2 bg-slate-800/50 p-1.5 rounded border border-slate-700">
                                    <label className="text-[10px] text-slate-400 uppercase font-bold pl-1">Test Samples:</label>
                                    <input type="number" value={testLimit} onChange={e => setTestLimit(parseInt(e.target.value))} className="bg-slate-900 text-white text-xs border border-slate-600 rounded px-2 py-1 w-20 text-center focus:border-cyan-500 focus:outline-none" />
                                </div>
                                <div className="flex flex-wrap gap-2 w-full sm:w-auto">
                                    <button onClick={() => handleStats('chi')} className="bg-indigo-900/50 border border-indigo-700/50 text-xs text-indigo-300 px-3 py-1.5 rounded hover:bg-indigo-800/50">Chi-Squared</button>
                                    <button onClick={() => handleStats('full')} className="bg-teal-900/50 border border-teal-700/50 text-xs text-teal-300 px-3 py-1.5 rounded hover:bg-teal-800/50">Extended Test</button>
                                    <button onClick={copyToClipboard} className="bg-slate-700 hover:bg-slate-600 text-xs text-white px-3 py-1.5 rounded min-w-[70px]">{copyStatus}</button>
                                </div>
                            </div>
                        </div>

                        {chiResult && (
                            <div className={`mb-4 px-4 py-3 rounded-md text-xs flex justify-between items-center font-mono border shadow-sm ${chiResult.passed ? 'bg-emerald-950/50 border-emerald-500/50 text-emerald-300' : 'bg-red-950/50 border-red-500/50 text-red-300'}`}>
                                <span className="font-bold">{chiResult.passed ? 'PASSED Frequency Test' : 'FAILED Frequency Test'}</span>
                                <span className="opacity-75">χ² = {chiResult.score.toFixed(2)} (Crit: 16.92)</span>
                            </div>
                        )}

                        {dieharderResults.length > 0 && (
                            <div className="mb-4 grid grid-cols-2 md:grid-cols-4 gap-3">
                                {dieharderResults.map(res => (
                                    <div key={res.name} className={`p-3 rounded border bg-slate-800/50 flex flex-col justify-between h-full ${res.status === 'PASS' ? 'border-emerald-500/40' : res.status === 'FAIL' ? 'border-red-500/40' : 'border-yellow-500/40'}`}>
                                        <div>
                                            <div className="flex justify-between items-start mb-1">
                                                <span className="font-bold text-xs text-slate-300 truncate pr-1" title={res.name}>{res.name}</span>
                                                <span className={`text-[9px] px-1.5 py-0.5 rounded font-mono font-bold flex-shrink-0 ${res.status === 'PASS' ? 'bg-emerald-900 text-emerald-300' : res.status === 'FAIL' ? 'bg-red-900 text-red-300' : 'bg-yellow-900 text-yellow-300'}`}>{res.status}</span>
                                            </div>
                                            <p className="text-[10px] text-slate-500 leading-tight mb-2 min-h-[2.5em]">{res.desc}</p>
                                        </div>
                                        <div className="text-right text-[10px] font-mono opacity-80 border-t border-slate-700/50 pt-1">
                                            {res.displayValue || `Score: ${res.score.toFixed(4)}`}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        <div className="font-mono text-purple-300 break-all text-sm leading-relaxed max-h-60 overflow-y-auto bg-slate-950/50 p-4 rounded border border-slate-800/50">
                            {sequence.join(', ')}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Playground;

import React, { useState } from 'react';
import { analyzeSequence } from '../services/geminiService';
import { AnalysisResult } from '../types';

interface HistoryItem {
  input: string;
  result: AnalysisResult;
  timestamp: number;
}

const Analyzer: React.FC = () => {
  const [inputSequence, setInputSequence] = useState('');
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setInputSequence(val);

    // Strict validation: allow numbers, commas, dots, minus, and spaces only
    if (val && !/^[\d\s,.-]*$/.test(val)) {
        setValidationError("Invalid characters detected. Only numbers, commas, and decimals allowed.");
    } else {
        setValidationError(null);
        if (error) setError(null); // Clear main error if user starts typing valid input
    }
  };

  const handleAnalyze = async () => {
    if (validationError) return;

    const rawInput = inputSequence.trim();
    if (!rawInput) return;

    const sequence = rawInput.split(',')
      .map(s => parseFloat(s.trim()))
      .filter(n => !isNaN(n));

    if (sequence.length < 3) {
      setError("Please enter at least 3 valid numbers.");
      return;
    }

    setIsLoading(true);
    setError(null);
    setResult(null);

    try {
      const analysis = await analyzeSequence(sequence);
      setResult(analysis);
      setHistory(prev => [
        { input: rawInput, result: analysis, timestamp: Date.now() },
        ...prev.slice(0, 9) // Keep last 10
      ]);
    } catch (err: any) {
      setError(err.message || "Analysis failed. Please try again or check your API key.");
    } finally {
      setIsLoading(false);
    }
  };

  const loadHistoryItem = (item: HistoryItem) => {
    setInputSequence(item.input);
    setResult(item.result);
    setValidationError(null);
    setError(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const loadDemo = (type: 'lcg' | 'fib') => {
    setValidationError(null);
    setError(null);
    if (type === 'lcg') {
      setInputSequence("1, 8, 11, 10, 5, 12");
    } else if (type === 'fib') {
      setInputSequence("0, 1, 1, 2, 3, 5, 8, 13, 21");
    }
  };

  return (
    <div className="space-y-6">
      <div className="glass-panel p-6 rounded-xl border-l-4 border-cyan-500 shadow-lg">
        <h2 className="text-xl font-bold text-white mb-4 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path stroke-linecap="round" stroke-linejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          Sequence Input
        </h2>

        <p className="text-slate-400 mb-4 text-sm">
          Enter a sequence of numbers separated by commas. The AI will attempt to reverse-engineer the generator.
        </p>

        <div className="flex gap-2 mb-2 relative">
          <input 
            type="text" 
            value={inputSequence}
            onChange={handleInputChange}
            onKeyDown={(e) => e.key === 'Enter' && !validationError && handleAnalyze()}
            placeholder="e.g., 3, 10, 31, 94..." 
            className={`flex-1 bg-slate-800 border ${validationError ? 'border-red-500 focus:border-red-500' : 'border-slate-700 focus:border-cyan-500'} text-white px-4 py-3 rounded-lg focus:outline-none font-mono transition-colors`}
          />
          <button 
            onClick={handleAnalyze} 
            disabled={isLoading || !!validationError}
            className="bg-cyan-600 hover:bg-cyan-500 text-white font-bold py-3 px-6 rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center shadow-lg shadow-cyan-900/20">
            {isLoading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Cracking...
              </>
            ) : (
              'Analyze'
            )}
          </button>
        </div>

        {validationError && (
          <div className="text-red-400 text-xs font-bold mb-4 animate-pulse">
            {validationError}
          </div>
        )}

        <div className="flex gap-2">
           <button onClick={() => loadDemo('lcg')} className="text-xs bg-slate-700 hover:bg-slate-600 text-cyan-300 px-3 py-1 rounded transition-colors">
             Load LCG Demo
           </button>
           <button onClick={() => loadDemo('fib')} className="text-xs bg-slate-700 hover:bg-slate-600 text-cyan-300 px-3 py-1 rounded transition-colors">
             Load Fibonacci Demo
           </button>
        </div>

        {error && (
          <div className="mt-4 p-3 bg-red-900/30 border border-red-800 text-red-300 rounded text-sm flex items-start">
             <svg className="w-5 h-5 mr-2 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
             {error}
          </div>
        )}
      </div>

      {result && (
        <div className="glass-panel p-6 rounded-xl border-t border-slate-700 animation-fade-in">

          <div className="flex justify-between items-center mb-6">
             <h3 className="text-2xl font-bold text-white">Analysis Report</h3>
             <span className="text-xs text-slate-500 border border-slate-700 px-2 py-1 rounded">Model: Gemini 3 Pro</span>
          </div>

          <h4 className="text-sm font-semibold text-slate-300 uppercase tracking-wider mb-4">Detected Algorithms</h4>
          <div className="grid grid-cols-1 gap-4 mb-6">
             {result.candidates.map((candidate, index) => (
                <div key={index} className={`bg-slate-800/50 p-4 rounded-lg border ${
                     candidate.confidence >= 80 ? 'border-emerald-500' :
                     candidate.confidence >= 50 ? 'border-yellow-500' :
                     'border-slate-600'
                   }`}>
                  <div className="flex justify-between items-start mb-2">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-mono text-lg font-bold text-white">{candidate.algorithm}</span>
                        {index === 0 && (
                          <span className="bg-emerald-900/50 text-emerald-400 text-xs px-2 py-0.5 rounded uppercase font-bold">Best Match</span>
                        )}
                      </div>
                      <p className="font-mono text-xs text-slate-400 mt-1">{candidate.parameters || 'No parameters detected'}</p>
                    </div>
                    <div className="flex flex-col items-end">
                       <span className={`text-2xl font-bold font-mono ${
                             candidate.confidence >= 80 ? 'text-emerald-400' :
                             candidate.confidence >= 50 ? 'text-yellow-400' :
                             'text-slate-400'
                           }`}>
                         {candidate.confidence}%
                       </span>
                       <span className="text-xs text-slate-500 uppercase">Confidence</span>
                    </div>
                  </div>
                  <p className="text-sm text-slate-300 border-t border-slate-700/50 pt-2 mt-2 leading-relaxed">
                    {candidate.explanation}
                  </p>
                </div>
             ))}
          </div>

          <div className="bg-slate-900/50 p-6 rounded-lg border border-slate-800">
            <h4 className="text-sm font-semibold text-cyan-400 uppercase tracking-wider mb-4 flex items-center">
              <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6"></path></svg>
              Predicted Next Sequence
            </h4>
            <div className="flex gap-4">
              {result.nextValues.map((val, index) => (
                <div key={index} className="bg-slate-950 border border-cyan-900 text-cyan-300 font-mono text-2xl py-4 px-6 rounded-lg shadow-lg flex-1 text-center relative overflow-hidden group">
                    <span className="relative z-10">{val}</span>
                    <div className="absolute top-0 right-0 p-1">
                      <span className="text-[10px] text-slate-600">n+{index + 1}</span>
                    </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {history.length > 0 && (
        <div className="glass-panel p-6 rounded-xl border border-slate-700/50 animation-fade-in mt-6">
          <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4">Recent Analyses</h4>
