type FormParams = {
    [K in keyof GeneratorParams]: string;
};

const defaultFormParams: FormParams = {
    a: '1664525', c: '1013904223', m: '4294967296', seed: '12345',
    seed2: '54321', seed3: '9999', seed4: '10101',
    stringSeed: 'EntropyOracle', hexTap: 'B400',
    fibSeed1: '0', fibSeed2: '1',
    floatSeed: '0.5', paramR: '3.99', paramA: '1.4', paramB: '0.3', paramC: '2.66', paramDt: '0.01'
};

const getRandomInt = () => {
  const arr = new Uint32Array(1);
  window.crypto.getRandomValues(arr);
  return arr[0];
};

const getRandomFloat = (min: number, max: number) => {
    const arr = new Uint32Array(1);
    window.crypto.getRandomValues(arr);
    const val = arr[0] / 4294967295; // 0..1
    return (min + val * (max - min)).toFixed(5);
};

const Playground: React.FC = () => {
    const [activeCategory, setActiveCategory] = useState<GenCategory>('LCG & MLCG');
    const [mode, setMode] = useState<string>('lcg');
    const [countStr, setCountStr] = useState('10');
    const [testLimitStr, setTestLimitStr] = useState('1000');
    const [showDetails, setShowDetails] = useState(false);
    const [formParams, setFormParams] = useState<FormParams>(defaultFormParams);

    const [sequence, setSequence] = useState<number[]>([]);
    const [chiResult, setChiResult] = useState<{score: number, passed: boolean} | null>(null);
    const [dieharderResults, setDieharderResults] = useState<TestResult[]>([]);
    const [copyStatus, setCopyStatus] = useState('Copy');

    const canvasRef = useRef<HTMLCanvasElement>(null);

    const currentAlgo = algorithms.find(a => a.id === mode);
    const filteredAlgorithms = algorithms.filter(a => a.category === activeCategory);

    // Parse params from string state to numbers for the generator logic
    const params = useMemo((): GeneratorParams => {
        return {
            a: parseInt(formParams.a) || 0,
            c: parseInt(formParams.c) || 0,
            m: parseInt(formParams.m) || 1,
            seed: parseInt(formParams.seed) || 0,
            seed2: parseInt(formParams.seed2) || 0,
            seed3: parseInt(formParams.seed3) || 0,
            seed4: parseInt(formParams.seed4) || 0,
            fibSeed1: parseInt(formParams.fibSeed1) || 0,
            fibSeed2: parseInt(formParams.fibSeed2) || 0,
            floatSeed: parseFloat(formParams.floatSeed) || 0,
            paramR: parseFloat(formParams.paramR) || 0,
            paramA: parseFloat(formParams.paramA) || 0,
            paramB: parseFloat(formParams.paramB) || 0,
            paramC: parseFloat(formParams.paramC) || 0,
            paramDt: parseFloat(formParams.paramDt) || 0,
            stringSeed: formParams.stringSeed,
            hexTap: formParams.hexTap,
        };
    }, [formParams]);

    const count = parseInt(countStr) || 10;
    const testLimit = parseInt(testLimitStr) || 1000;

    const currentErrors = useMemo(() => {
        const errs: Record<string, string> = {};
        if (count <= 0) errs['count'] = "Count must be > 0";
        if (count > 50000) errs['count'] = "Max limit 50,000";

        if (testLimit < 1000) errs['testLimit'] = "Min 1000 samples required for reliable stats";
        if (testLimit > 1000000) errs['testLimit'] = "Max 1,000,000 samples to prevent freeze";

        // Seed Validation
        if (['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn', 'xorshift', 'splitmix', 'mulberry', 'mt19937'].includes(mode)) {
             if (formParams.seed === '' || isNaN(params.seed!)) {
                 errs['seed'] = "Valid integer seed required";
             }
        }

        if (['xorshift', 'splitmix', 'mulberry', 'xoroshiro128plus', 'xorshift1024', 'mt19937'].includes(mode)) {
             if (params.seed === 0) errs['seed'] = "Seed must be non-zero for this algorithm";
        }

        if (['lcg', 'minstd', 'carbon'].includes(mode)) {
            if (params.m! <= 0) errs['m'] = "Modulus must be > 0";
            if (params.a! < 0) errs['a'] = "Multiplier must be >= 0";
            if (params.m! > 0 && params.seed! >= params.m!) errs['seed'] = `Seed must be < Modulus (${params.m})`;
        }

        if (mode.includes('lfsr') && !/^[0-9A-Fa-f]+$/.test(formParams.hexTap)) {
            errs['hexTap'] = "Invalid Hexadecimal";
        }

        if (mode === 'logistic' || mode === 'tent') {
            if (params.paramR! > 4.0) errs['paramR'] = "r should be <= 4.0";
            if (params.paramR! < 0) errs['paramR'] = "r must be >= 0";
            if (params.floatSeed! < 0 || params.floatSeed! > 1) errs['floatSeed'] = "X0 must be in [0, 1]";
        }

        if (['lorenz', 'rossler', 'ikeda', 'henon'].includes(mode)) {
             if (params.paramDt! <= 0) errs['paramDt'] = "dt must be > 0";
             if (params.paramDt! > 0.5) errs['paramDt'] = "dt too large for stability";
        }

        return errs;
    }, [mode, params, formParams, count, testLimit]);

    const hasErrors = Object.keys(currentErrors).length > 0;

    const handleInputChange = (key: keyof FormParams, value: string, type: 'int' | 'float' | 'hex' | 'posInt' = 'int') => {
        let pattern;
        switch(type) {
            case 'int': pattern = /^-?\d*$/; break;
            case 'posInt': pattern = /^\d*$/; break;
            case 'float': pattern = /^-?\d*\.?\d*$/; break;
            case 'hex': pattern = /^[0-9a-fA-F]*$/; break;
            default: pattern = /.*/;
        }
        if (pattern.test(value)) {
            setFormParams(prev => ({ ...prev, [key]: value }));
        }
    };

    const handleRawSetParam = (key: keyof FormParams, val: string) => {
        setFormParams(prev => ({ ...prev, [key]: val }));
    };

    const randomizeCurrent = () => {
        const arr = new Uint32Array(4);
        window.crypto.getRandomValues(arr);

        let newParams = { ...formParams };

        if (['lcg', 'minstd', 'mt19937'].includes(mode)) {
           newParams.seed = arr[0].toString();
        } else if (mode.includes('lfsr')) {
           newParams.seed = arr[0].toString();
           if (mode === 'lfsr64') newParams.stringSeed = (BigInt(arr[0]) + BigInt(arr[1])).toString();
        } else if (['logistic', 'tent', 'henon', 'lorenz', 'rossler', 'ikeda'].includes(mode)) {
           newParams.floatSeed = getRandomFloat(0.05, 0.95);

           if (mode === 'logistic') newParams.paramR = getRandomFloat(3.6, 4.0);
           if (mode === 'tent') newParams.paramR = getRandomFloat(1.5, 1.99);
           if (mode === 'henon') {
               newParams.paramA = getRandomFloat(1.2, 1.42);
               newParams.paramB = getRandomFloat(0.2, 0.35);
           }
           if (mode === 'ikeda') newParams.paramA = getRandomFloat(0.8, 0.95);
           if (mode === 'lorenz') {
               newParams.paramA = getRandomFloat(9.0, 11.0); 
               newParams.paramB = getRandomFloat(24.0, 30.0);
               newParams.paramC = getRandomFloat(2.5, 2.8);
           }
           if (mode === 'rossler') {
               newParams.paramA = getRandomFloat(0.15, 0.25);
               newParams.paramB = getRandomFloat(0.15, 0.25);
               newParams.paramC = getRandomFloat(5.0, 6.5);
           }
        } else {
            newParams.seed = arr[0].toString();
            newParams.seed2 = arr[1].toString();
        }

        if (mode === 'lcg' || mode === 'custom') {
            newParams.a = getRandomInt().toString();
            newParams.c = getRandomInt().toString();
            newParams.m = '4294967296';
        }

        setFormParams(newParams);
    };

    const setDefaultParams = (id: string) => {
        let p: FormParams = { ...formParams };
        if (id === 'lcg') { p.a='1664525'; p.c='1013904223'; p.m='4294967296'; p.seed='12345'; }
        if (id === 'randu') { p.a='65539'; p.c='0'; p.m='2147483648'; p.seed='1'; }
        if (id === 'logistic') { p.floatSeed='0.5'; p.paramR='3.99'; }
        if (id === 'lorenz') { p.floatSeed='0.1'; p.paramA='10'; p.paramB='28'; p.paramC='2.66'; p.paramDt='0.01'; }
        if (id === 'rossler') { p.floatSeed='0.1'; p.paramA='0.2'; p.paramB='0.2'; p.paramC='5.7'; p.paramDt='0.05'; }
        if (id === 'henon') { p.floatSeed='0.1'; p.paramA='1.4'; p.paramB='0.3'; }
        if (id === 'ikeda') { p.floatSeed='0.1'; p.paramA='0.9'; }
        if (id === 'lfsr8') { p.seed='31'; p.hexTap='1D'; }
        if (id === 'xoroshiro128plus') { p.seed='123456'; p.seed2='987654'; }
        if (id === 'mt19937') { p.seed='5489'; }
        setFormParams(p);
    };

    const handleModeChange = (id: string) => {
        setMode(id);
        setSequence([]);
        setChiResult(null);
        setDieharderResults([]);
        setShowDetails(false);
        setDefaultParams(id);
    };

    const handleCategoryChange = (cat: GenCategory) => {
        setActiveCategory(cat);
        const first = algorithms.find(a => a.category === cat);
        if (first) handleModeChange(first.id);
    };

    const drawChaos = useCallback(() => {
        if (activeCategory !== 'Chaotic') return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const width = canvas.width;
        const height = canvas.height;
        ctx.fillStyle = '#050b14';
        ctx.fillRect(0, 0, width, height);

        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(34, 211, 238, 0.4)';
        ctx.fillStyle = 'rgba(34, 211, 238, 0.6)';

        if (mode === 'logistic' || mode === 'tent') {
            ctx.fillStyle = 'rgba(168, 85, 247, 0.4)';
            const rMin = (mode === 'logistic') ? 2.0 : 1.0;
            const rMax = (mode === 'logistic') ? 4.0 : 2.0;

            for (let px = 0; px < width; px++) {
                const r = rMin + (px / width) * (rMax - rMin);
                let x = 0.5;
                // warmup
                for (let i = 0; i < 50; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                }
                // draw
                for (let i = 0; i < 30; i++) {
                    if (mode === 'logistic') x = r * x * (1 - x);
                    else x = (x < 0.5) ? r * x : r * (1 - x);
                    const py = height - (x * height);
                    ctx.fillRect(px, py, 1, 1);
                }
            }
            // Indicator
            const currentR = params.paramR ?? 0;
            if (currentR >= rMin && currentR <= rMax) {
                const lineX = ((currentR - rMin) / (rMax - rMin)) * width;
                ctx.strokeStyle = '#22d3ee';
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(lineX, 0);
                ctx.lineTo(lineX, height);
                ctx.stroke();
            }
        } else if (mode === 'lorenz') {
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.01;
             const a = params.paramA ?? 10, b = params.paramB ?? 28, c = params.paramC ?? 2.66;

             for(let i=0; i<100; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 10, scaleY = 5, offX = width/2;
             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, height - (z * scaleY));

             for(let i=0; i<10000; i++) {
                let dx = a*(y-x), dy=x*(b-z)-y, dz=x*y-c*z;
                x+=dx*dt; y+=dy*dt; z+=dz*dt;
                ctx.lineTo(offX + x * scaleX, height - (z * scaleY));
             }
             ctx.stroke();

        } else if (mode === 'rossler') {
             let x = params.floatSeed ?? 0.1, y = 1.0, z = 1.0;
             const dt = params.paramDt ?? 0.05;
             const a = params.paramA ?? 0.2, b = params.paramB ?? 0.2, c = params.paramC ?? 5.7;

             for(let i=0; i<100; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
             }

             const scaleX = 8, scaleY = 8, offX = width/2, offY = height/2 + 50;
             ctx.strokeStyle = 'rgba(236, 72, 153, 0.4)';
             ctx.beginPath();
             ctx.moveTo(offX + x * scaleX, offY - (y * scaleY)); 

             for(let i=0; i<10000; i++) {
                 let dx = -y - z, dy = x + a*y, dz = b + z*(x-c);
                 x+=dx*dt; y+=dy*dt; z+=dz*dt;
                 ctx.lineTo(offX + x * scaleX, offY - (y * scaleY));
             }
             ctx.stroke();
        }
    }, [mode, activeCategory, params]);

    useEffect(() => {
        if (activeCategory === 'Chaotic') {
            const timer = setTimeout(drawChaos, 50);
            return () => clearTimeout(timer);
        }
    }, [drawChaos, activeCategory]);

    const handleGenerate = () => {
        if (hasErrors) return;
        const seq = generateInternalSequence(mode, params, count);
        setSequence(seq);
        setChiResult(null);
        setDieharderResults([]);
    };

    const handleStats = (type: 'chi' | 'full') => {
        if (hasErrors) return;
        const seq = generateInternalSequence(mode, params, Math.max(testLimit, 1000));
        if (type === 'chi') {
            setChiResult(performChiSquared(seq));
        } else {
            setDieharderResults(performDieharder(seq));
        }
    };

    const copyToClipboard = () => {
        navigator.clipboard.writeText(sequence.join(', '));
        setCopyStatus('Copied!');
        setTimeout(() => setCopyStatus('Copy'), 2000);
    };

    const renderChaosControls = () => {
        if (mode === 'lorenz' || mode === 'rossler') {
            return (
                <div className="absolute top-3 right-4 z-20 bg-slate-900/90 p-3 rounded-lg border border-slate-700/50 w-48 backdrop-blur-md shadow-xl">
                     <div className="space-y-3">
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1" title="Time step for integration (Euler method). Smaller values yield more accurate but slower trajectories.">
                                <span>DT (Step) ⓘ</span>
                                <span>{params.paramDt}</span>
                            </label>
                            <input type="range" min="0.001" max="0.1" step="0.001" value={formParams.paramDt} onChange={(e) => handleRawSetParam('paramDt', e.target.value)} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1" title={mode === 'lorenz' ? "Sigma: Prandtl number, representing the ratio of fluid viscosity to thermal conductivity." : "a: Affects the x-y plane oscillation."}>
                                <span>{mode === 'lorenz' ? 'Sigma' : 'a'} ⓘ</span>
                                <span>{params.paramA}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 50 : 1} step={mode === 'lorenz' ? 0.1 : 0.01} value={formParams.paramA} onChange={(e) => handleRawSetParam('paramA', e.target.value)} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1" title={mode === 'lorenz' ? "Rho: Rayleigh number, representing the temperature difference driving convection." : "b: Controls the tendency of the trajectory to jump out of the x-y plane."}>
                                <span>{mode === 'lorenz' ? 'Rho' : 'b'} ⓘ</span>
                                <span>{params.paramB}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 100 : 1} step={mode === 'lorenz' ? 0.1 : 0.01} value={formParams.paramB} onChange={(e) => handleRawSetParam('paramB', e.target.value)} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                         <div>
                            <label className="flex justify-between text-[10px] text-slate-400 font-bold uppercase mb-1" title={mode === 'lorenz' ? "Beta: Geometric factor related to the physical dimensions of the convection layer." : "c: The threshold for large excursions in the Z direction."}>
                                <span>{mode === 'lorenz' ? 'Beta' : 'c'} ⓘ</span>
                                <span>{params.paramC}</span>
                            </label>
                            <input type="range" min="0" max={mode === 'lorenz' ? 10 : 20} step="0.01" value={formParams.paramC} onChange={(e) => handleRawSetParam('paramC', e.target.value)} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-400" />
                         </div>
                     </div>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="glass-panel p-6 rounded-xl border-t border-b border-purple-500/30 shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-purple-600/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>

            <div className="relative z-10">
                <h2 className="text-2xl font-black text-white mb-6 flex items-center tracking-tight">
                    <span className="bg-clip-text text-transparent bg-gradient-to-r from-purple-400 to-pink-400">GENERATOR LAB</span>
                </h2>

                <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-700/50 pb-2">
                    {categories.map(cat => (
                        <button
                            key={cat}
                            onClick={() => handleCategoryChange(cat)}
                            className={`px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-lg transition-all ${
                                activeCategory === cat ? 'bg-slate-800 text-purple-400 border border-purple-500/50' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-800/50 border border-transparent'
                            }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 mb-8">
                    {filteredAlgorithms.map(algo => (
                        <button
                            key={algo.id}
                            onClick={() => handleModeChange(algo.id)}
                            className={`px-3 py-3 rounded-lg text-xs font-bold transition-all text-left border relative overflow-hidden group shadow-sm flex flex-col justify-center min-h-[3.5rem] ${
                                mode === algo.id ? 'bg-purple-600 border-purple-400 text-white shadow-purple-900/50' : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:border-purple-500/50 hover:text-slate-200'
                            }`}
                        >
                            <span className="relative z-10 truncate w-full">{algo.name}</span>
                            {mode === algo.id && <div className="absolute inset-0 bg-gradient-to-br from-purple-600 to-indigo-600 opacity-100 z-0"></div>}
                        </button>
                    ))}
                </div>

                {currentAlgo && (
                    <div className="bg-slate-900/60 border-l-4 border-cyan-500 p-5 rounded-r-lg mb-8 flex flex-col sm:flex-row justify-between items-start gap-4 shadow-inner relative">
                        <div className="flex-1">
                            <h3 className="text-white font-bold text-lg mb-2 flex flex-wrap items-center gap-2">
                                {currentAlgo.name}
                                <span className="px-2 py-0.5 rounded-full bg-slate-800 text-[10px] text-cyan-400 border border-slate-700 uppercase tracking-widest">{currentAlgo.category}</span>
                            </h3>
                            <p className="text-slate-300 text-sm leading-relaxed">{currentAlgo.desc}</p>

                            <button 
                                onClick={() => setShowDetails(!showDetails)}
                                className="mt-3 text-[10px] font-bold uppercase tracking-widest text-purple-400 hover:text-purple-300 flex items-center"
                            >
                                {showDetails ? 'Hide Details' : 'Show Key Characteristics'}
                                <svg className={`w-3 h-3 ml-1 transform transition-transform ${showDetails ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                            </button>
                        </div>
                        <a href={currentAlgo.wiki} target="_blank" rel="noopener noreferrer" className="flex-shrink-0 text-cyan-500 hover:text-cyan-300 transition-colors text-xs font-mono border border-cyan-900/50 bg-cyan-950/30 px-3 py-2 rounded hover:border-cyan-500">
                            Wiki
                        </a>

                        {showDetails && (
                            <div className="absolute top-full left-0 w-full mt-2 bg-slate-900 border border-slate-700 p-4 rounded-lg shadow-xl z-20 animation-fade-in text-left">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <h5 className="text-[10px] text-emerald-400 uppercase font-bold mb-2 border-b border-emerald-900/50 pb-1">Characteristics</h5>
                                        <ul className="list-disc list-inside text-xs text-slate-300 space-y-1">
                                            {currentAlgo.characteristics?.map((c, i) => <li key={i}>{c}</li>) || <li className="italic text-slate-500">No data available</li>}
                                        </ul>
                                    </div>
                                    <div>
                                        <h5 className="text-[10px] text-red-400 uppercase font-bold mb-2 border-b border-red-900/50 pb-1">Limitations</h5>
                                        <ul className="list-disc list-inside text-xs text-slate-300 space-y-1">
                                            {currentAlgo.limitations?.map((l, i) => <li key={i}>{l}</li>) || <li className="italic text-slate-500">No data available</li>}
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {activeCategory === 'Chaotic' && (
                    <div className="mb-8 relative bg-slate-950 rounded-xl border border-slate-800 p-1 overflow-hidden h-64">
                         <div className="absolute top-3 left-4 z-10 pointer-events-none">
                            <label className="text-xs font-bold text-purple-300 bg-slate-900/80 px-2 py-1 rounded backdrop-blur-sm border border-purple-500/20">
                                {mode === 'lorenz' ? 'Phase Space (X vs Z)' : mode === 'rossler' ? 'Phase Space (X vs Y)' : 'Visualization'}
                            </label>
                         </div>

                        {renderChaosControls()}

                        <canvas 
                            ref={canvasRef} 
                            width={800} 
                            height={250} 
                            className="w-full h-full rounded-lg bg-[#050b14] cursor-crosshair"
                            onClick={(e) => {
                                if (mode !== 'logistic' && mode !== 'tent') return;
                                const rect = e.currentTarget.getBoundingClientRect();
                                const x = e.clientX - rect.left;
                                const rMin = mode === 'logistic' ? 2.0 : 1.0;
                                const rMax = mode === 'logistic' ? 4.0 : 2.0;
                                const newVal = parseFloat((rMin + (x/rect.width) * (rMax - rMin)).toFixed(4)).toString();
                                handleRawSetParam('paramR', newVal);
                            }}
                        />
                    </div>
                )}

                <div className="bg-slate-800/30 rounded-xl p-8 border border-slate-700/50 mb-6">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-6 border-b border-slate-700/50 pb-2">Configuration Variables</h4>

                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-x-8 gap-y-10">
                        {/* LCG Inputs */}
                        {['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn'].includes(mode) && (
                            <>
                                <div className="col-span-1 md:col-span-4 flex justify-between">
                                    <label className="text-slate-400 font-bold text-xs uppercase">LCG Parameters</label>
                                    <button onClick={randomizeCurrent} className="text-cyan-400 text-xs uppercase font-bold hover:text-cyan-300">Randomize All</button>
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Multiplier (a)</label>
                                    <input type="text" inputMode="numeric" value={formParams.a} onChange={e => handleInputChange('a', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['a'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['a'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['a']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Increment (c)</label>
                                    <input type="text" inputMode="numeric" value={formParams.c} onChange={e => handleInputChange('c', e.target.value, 'int')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" />
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Modulus (m)</label>
                                    <input type="text" inputMode="numeric" value={formParams.m} onChange={e => handleInputChange('m', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['m'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['m'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['m']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Seed</label>
                                    <input type="text" inputMode="numeric" value={formParams.seed} onChange={e => handleInputChange('seed', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                </div>
                            </>
                        )}

                        {/* Chaos Inputs */}
                        {(['logistic', 'tent', 'lorenz', 'rossler', 'ikeda', 'henon'].includes(mode)) && (
                            <>
                                <div className="col-span-1 md:col-span-4 flex justify-between">
                                    <label className="text-slate-400 font-bold text-xs uppercase">Chaos Parameters</label>
                                    <button onClick={randomizeCurrent} className="text-cyan-400 text-xs uppercase font-bold hover:text-cyan-300">Randomize All</button>
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Initial X</label>
                                    <input type="text" inputMode="decimal" value={formParams.floatSeed} onChange={e => handleInputChange('floatSeed', e.target.value, 'float')} className={`w-full bg-slate-900/50 border ${currentErrors['floatSeed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['floatSeed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['floatSeed']}</span>}
                                </div>
                                {['logistic', 'tent'].includes(mode) && (
                                    <div>
                                        <label className="block text-slate-400 text-xs font-bold mb-2">Rate (r/mu)</label>
                                        <input type="text" inputMode="decimal" value={formParams.paramR} onChange={e => handleInputChange('paramR', e.target.value, 'float')} className={`w-full bg-slate-900/50 border ${currentErrors['paramR'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                        {currentErrors['paramR'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['paramR']}</span>}
                                    </div>
                                )}
                                {mode === 'henon' && (
                                    <>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param A (Canonic 1.4)</label><input type="text" inputMode="decimal" value={formParams.paramA} onChange={e => handleInputChange('paramA', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param B (Canonic 0.3)</label><input type="text" inputMode="decimal" value={formParams.paramB} onChange={e => handleInputChange('paramB', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                        <div className="col-span-full mt-2 text-[10px] text-slate-500 flex flex-wrap gap-2 border-t border-slate-800 pt-2">
                                            <span className="font-bold opacity-50">PRESETS:</span>
                                            {henonPresets.map(p => (
                                                 <button key={p.name} onClick={() => { handleRawSetParam('paramA', p.a); handleRawSetParam('paramB', p.b); }} className="text-purple-400 hover:text-purple-300 underline cursor-help" title={p.desc}>{p.name}</button>
                                            ))}
                                        </div>
                                    </>
                                )}
                                {mode === 'ikeda' && (
                                    <>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param u (Canonic 0.9)</label><input type="text" inputMode="decimal" value={formParams.paramA} onChange={e => handleInputChange('paramA', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                        <div className="col-span-full mt-2 text-[10px] text-slate-500 flex flex-wrap gap-2 border-t border-slate-800 pt-2">
                                            <span className="font-bold opacity-50">PRESETS:</span>
                                            {ikedaPresets.map(p => (
                                                 <button key={p.name} onClick={() => handleRawSetParam('paramA', p.u)} className="text-purple-400 hover:text-purple-300 underline cursor-help" title={p.desc}>{p.name}</button>
                                            ))}
                                        </div>
                                    </>
                                )}
                                {['lorenz', 'rossler'].includes(mode) && (
                                    <>
                                        <div>
                                            <label className="block text-slate-400 text-xs font-bold mb-2">Time Step (dt)</label>
                                            <input type="text" inputMode="decimal" value={formParams.paramDt} onChange={e => handleInputChange('paramDt', e.target.value, 'float')} className={`w-full bg-slate-900/50 border ${currentErrors['paramDt'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                            {currentErrors['paramDt'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['paramDt']}</span>}
                                        </div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param A (Sigma/a)</label><input type="text" inputMode="decimal" value={formParams.paramA} onChange={e => handleInputChange('paramA', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param B (Rho/b)</label><input type="text" inputMode="decimal" value={formParams.paramB} onChange={e => handleInputChange('paramB', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                        <div><label className="block text-slate-400 text-xs font-bold mb-2">Param C (Beta/c)</label><input type="text" inputMode="decimal" value={formParams.paramC} onChange={e => handleInputChange('paramC', e.target.value, 'float')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                    </>
                                )}
                            </>
                        )}

                        {/* LFSR 8/16/32 */}
                        {(mode === 'lfsr8' || mode === 'lfsr' || mode === 'lfsr32' || mode === 'lfsr64') && (
                             <>
                                {mode !== 'lfsr64' ? (
                                    <div>
                                        <label className="block text-slate-400 text-xs font-bold mb-2">Seed (Int)</label>
                                        <input type="text" inputMode="numeric" value={formParams.seed} onChange={e => handleInputChange('seed', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                        {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                    </div>
                                ) : (
                                    <div><label className="block text-slate-400 text-xs font-bold mb-2">Seed (BigInt String)</label><input type="text" inputMode="numeric" value={formParams.stringSeed} onChange={e => handleInputChange('stringSeed', e.target.value, 'posInt')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                )}

                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Tap (Hex)</label>
                                    <input type="text" value={formParams.hexTap} onChange={e => handleInputChange('hexTap', e.target.value, 'hex')} className={`w-full bg-slate-900/50 border ${currentErrors['hexTap'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['hexTap'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['hexTap']}</span>}
                                    <div className="mt-2 text-[10px] text-slate-500 flex flex-wrap gap-2">
                                        <span className="w-full font-bold opacity-50">PRESETS:</span>
                                        {(mode === 'lfsr8' ? lfsr8Presets : mode === 'lfsr' ? lfsr16Presets : mode === 'lfsr32' ? lfsr32Presets : lfsr64Presets).map(p => (
                                            <button key={p.name} onClick={() => handleRawSetParam('hexTap', p.tap)} className="text-purple-400 hover:text-purple-300 underline" title={p.desc}>{p.name}</button>
                                        ))}
                                    </div>
                                </div>
                             </>
                        )}

                        {/* Xorshift / Splitmix / Mulberry / Xoroshiro / MT19937 */}
                        {['xorshift', 'xorshift1024', 'xoroshiro128plus', 'splitmix', 'mulberry', 'mt19937'].includes(mode) && (
                            <>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Seed 1</label>
                                    <input type="text" inputMode="numeric" value={formParams.seed} onChange={e => handleInputChange('seed', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                </div>
                                {['xoroshiro128plus', 'xorshift1024'].includes(mode) && (
                                     <div><label className="block text-slate-400 text-xs font-bold mb-2">Seed 2</label><input type="text" inputMode="numeric" value={formParams.seed2} onChange={e => handleInputChange('seed2', e.target.value, 'int')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" /></div>
                                )}
                                {mode === 'xorshift' && (
                                    <div className="col-span-full mt-2 text-[10px] text-slate-500 flex flex-wrap gap-2 border-t border-slate-800 pt-2">
                                        <span className="font-bold opacity-50">VARIANTS:</span>
                                        {xorshiftPresets.map(p => (
                                             <button key={p.name} onClick={() => console.log('Preset selected (visual only for hardcoded xorshift)')} className="text-purple-400 hover:text-purple-300 underline cursor-help" title={p.desc}>{p.name}</button>
                                        ))}
                                        <span className="text-slate-600 ml-2">(Note: Standard implementation uses fixed shifts 13, 17, 5)</span>
                                    </div>
                                )}
                            </>
                        )}

                         {/* Fallback for others not explicitly handled above */}
                        {!['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn', 'logistic', 'tent', 'lorenz', 'rossler', 'ikeda', 'henon', 'lfsr8', 'lfsr', 'lfsr32', 'lfsr64', 'xorshift', 'xorshift1024', 'xoroshiro128plus', 'splitmix', 'mulberry', 'mt19937'].includes(mode) && !mode.includes('lfsr') && (
                             <div>
                                <label className="block text-slate-400 text-xs font-bold mb-2">Seed</label>
                                <input type="text" inputMode="numeric" value={formParams.seed} onChange={e => handleInputChange('seed', e.target.value, 'int')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" />
                             </div>
                        )}

                        <div className="col-span-1 sm:col-span-2 xl:col-span-4 border-t border-slate-700/50 pt-8 mt-6">
                            <div className="flex flex-col sm:flex-row items-center gap-6 bg-slate-900/40 p-4 rounded-lg border border-slate-800">
                                <div className="w-full flex-1">
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Display Length (3 - 500)</label>
                                    <input type="range" min="3" max="500" value={countStr} onChange={e => setCountStr(e.target.value)} className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                                </div>
                                <div className="w-full sm:w-24">
                                    <input type="text" inputMode="numeric" value={countStr} onChange={e => {
                                        if (/^\d*$/.test(e.target.value)) setCountStr(e.target.value);
                                    }} className={`w-full bg-slate-900/50 border ${currentErrors['count'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-center font-bold text-lg font-mono`} />
                                    {currentErrors['count'] && <span className="text-red-500 text-[10px] block mt-1 text-center">{currentErrors['count']}</span>}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6">
                    <button onClick={handleGenerate} className="w-full sm:w-auto group relative bg-purple-600 hover:bg-purple-500 text-white font-bold py-3 px-8 rounded-lg transition-all shadow-lg shadow-purple-900/30 overflow-hidden">
                        Generate Sequence
                    </button>
                </div>

                {sequence.length > 0 && (
                    <div className="bg-slate-900/80 p-5 rounded-lg border border-slate-700 shadow-xl relative group animation-fade-in">
                        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center mb-4 pb-2 border-b border-slate-800 gap-4">
                            <h3 className="text-xs text-purple-400 uppercase tracking-widest font-bold flex items-center">
                                <span className="w-2 h-2 rounded-full bg-purple-500 mr-2"></span>
                                Output Sequence ({sequence.length})
                            </h3>
                            <div className="flex flex-col sm:flex-row gap-4 items-center w-full xl:w-auto">
                                <div className="flex items-center gap-2 bg-slate-800/50 p-1.5 rounded border border-slate-700 relative">
                                    <label className="text-[10px] text-slate-400 uppercase font-bold pl-1">Test Samples:</label>
                                    <input type="text" inputMode="numeric" value={testLimitStr} onChange={e => {
                                         if (/^\d*$/.test(e.target.value)) setTestLimitStr(e.target.value);
                                    }} className={`bg-slate-900 text-white text-xs border ${currentErrors['testLimit'] ? 'border-red-500' : 'border-slate-600'} rounded px-2 py-1 w-20 text-center focus:outline-none font-mono`} />
                                    {currentErrors['testLimit'] && (
                                        <div className="absolute top-full left-0 mt-1 w-40 bg-red-900 text-white text-[10px] p-1 rounded z-50">
                                            {currentErrors['testLimit']}
                                        </div>
                                    )}
                                </div>
                                <div className="flex flex-wrap gap-2 w-full sm:w-auto">
                                    <button onClick={() => handleStats('chi')} className="bg-indigo-900/50 border border-indigo-700/50 text-xs text-indigo-300 px-3 py-1.5 rounded hover:bg-indigo-800/50">Chi-Squared</button>
                                    <button onClick={() => handleStats('full')} className="bg-teal-900/50 border border-teal-700/50 text-xs text-teal-300 px-3 py-1.5 rounded hover:bg-teal-800/50">Extended Test</button>
                                    <button onClick={copyToClipboard} className="bg-slate-700 hover:bg-slate-600 text-xs text-white px-3 py-1.5 rounded min-w-[70px]">{copyStatus}</button>
                                </div>
                            </div>
                        </div>

                        {chiResult && (
                            <div className={`mb-4 px-4 py-3 rounded-md text-xs flex justify-between items-center font-mono border shadow-sm ${chiResult.passed ? 'bg-emerald-950/50 border-emerald-500/50 text-emerald-300' : 'bg-red-950/50 border-red-500/50 text-red-300'}`}>
                                <span className="font-bold">{chiResult.passed ? 'PASSED Frequency Test' : 'FAILED Frequency Test'}</span>
                                <span className="opacity-75">χ² = {chiResult.score.toFixed(2)} (Crit: 16.92)</span>
                            </div>
                        )}

                        {dieharderResults.length > 0 && (
                            <div className="mb-4 grid grid-cols-2 md:grid-cols-4 gap-3">
                                {dieharderResults.map(res => (
                                    <div key={res.name} className={`p-3 rounded border bg-slate-800/50 flex flex-col justify-between h-full ${res.status === 'PASS' ? 'border-emerald-500/40' : res.status === 'FAIL' ? 'border-red-500/40' : 'border-yellow-500/40'}`}>
                                        <div>
                                            <div className="flex justify-between items-start mb-1">
                                                <span className="font-bold text-xs text-slate-300 truncate pr-1" title={res.name}>{res.name}</span>
                                                <span className={`text-[9px] px-1.5 py-0.5 rounded font-mono font-bold flex-shrink-0 ${res.status === 'PASS' ? 'bg-emerald-900 text-emerald-300' : res.status === 'FAIL' ? 'bg-red-900 text-red-300' : 'bg-yellow-900 text-yellow-300'}`}>{res.status}</span>
                                            </div>
                                            <p className="text-[10px] text-slate-500 leading-tight mb-2 min-h-[2.5em]">{res.desc}</p>
                                        </div>
                                        <div className="text-right text-[10px] font-mono opacity-80 border-t border-slate-700/50 pt-1">
                                            {res.displayValue || `Score: ${res.score.toFixed(4)}`}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        <div className="font-mono text-purple-300 break-all text-sm leading-relaxed max-h-60 overflow-y-auto bg-slate-950/50 p-4 rounded border border-slate-800/50">
                            {sequence.join(', ')}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

