type FormParams = {
    [K in keyof GeneratorParams]: string;
};

const defaultFormParams: FormParams = {
    a: '1664525', c: '1013904223', m: '4294967296', seed: '12345',
    seed2: '54321', seed3: '9999', seed4: '10101',
    stringSeed: 'EntropyWizard', hexTap: 'B400',
