                    </div>
                )}

                {activeCategory === 'Chaotic' && (
                    <div className="mb-8 relative bg-slate-950 rounded-xl border border-slate-800 p-1 overflow-hidden h-64">
                         <div className="absolute top-3 left-4 z-10 pointer-events-none">
                            <label className="text-xs font-bold text-purple-300 bg-slate-900/80 px-2 py-1 rounded backdrop-blur-sm border border-purple-500/20">
                                {mode === 'lorenz' ? 'Phase Space (X vs Z)' : mode === 'rossler' ? 'Phase Space (X vs Y)' : 'Visualization'}
                            </label>
                         </div>

                        {renderChaosControls()}

                        <canvas 
                            ref={canvasRef} 
                            width={800} 
                            height={250} 
                            className="w-full h-full rounded-lg bg-[#050b14] cursor-crosshair"
                            onClick={(e) => {
                                if (mode !== 'logistic' && mode !== 'tent') return;
                                const rect = e.currentTarget.getBoundingClientRect();
                                const x = e.clientX - rect.left;
                                const rMin = mode === 'logistic' ? 2.0 : 1.0;
                                const rMax = mode === 'logistic' ? 4.0 : 2.0;
                                const newVal = parseFloat((rMin + (x/rect.width) * (rMax - rMin)).toFixed(4)).toString();
                                handleRawSetParam('paramR', newVal);
                            }}
                        />
                    </div>
                )}

                <div className="bg-slate-800/30 rounded-xl p-8 border border-slate-700/50 mb-6">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-6 border-b border-slate-700/50 pb-2">Configuration Variables</h4>

                    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-x-8 gap-y-10">
                        {/* LCG Inputs */}
                        {['lcg', 'randu', 'zx81', 'nr', 'minstd', 'carbon', 'ggn'].includes(mode) && (
                            <>
                                <div className="col-span-1 md:col-span-4 flex justify-between">
                                    <label className="text-slate-400 font-bold text-xs uppercase">LCG Parameters</label>
                                    <button onClick={randomizeCurrent} className="text-cyan-400 text-xs uppercase font-bold hover:text-cyan-300">Randomize All</button>
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Multiplier (a)</label>
                                    <input type="text" inputMode="numeric" value={formParams.a} onChange={e => handleInputChange('a', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['a'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['a'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['a']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Increment (c)</label>
                                    <input type="text" inputMode="numeric" value={formParams.c} onChange={e => handleInputChange('c', e.target.value, 'int')} className="w-full bg-slate-900/50 border border-slate-700/50 text-white px-3 py-2 rounded-lg text-xs font-mono" />
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Modulus (m)</label>
                                    <input type="text" inputMode="numeric" value={formParams.m} onChange={e => handleInputChange('m', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['m'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['m'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['m']}</span>}
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Seed</label>
                                    <input type="text" inputMode="numeric" value={formParams.seed} onChange={e => handleInputChange('seed', e.target.value, 'int')} className={`w-full bg-slate-900/50 border ${currentErrors['seed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['seed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['seed']}</span>}
                                </div>
                            </>
                        )}

                        {/* Chaos Inputs */}
                        {(['logistic', 'tent', 'lorenz', 'rossler', 'ikeda', 'henon'].includes(mode)) && (
                            <>
                                <div className="col-span-1 md:col-span-4 flex justify-between">
                                    <label className="text-slate-400 font-bold text-xs uppercase">Chaos Parameters</label>
                                    <button onClick={randomizeCurrent} className="text-cyan-400 text-xs uppercase font-bold hover:text-cyan-300">Randomize All</button>
                                </div>
                                <div>
                                    <label className="block text-slate-400 text-xs font-bold mb-2">Initial X</label>
                                    <input type="text" inputMode="decimal" value={formParams.floatSeed} onChange={e => handleInputChange('floatSeed', e.target.value, 'float')} className={`w-full bg-slate-900/50 border ${currentErrors['floatSeed'] ? 'border-red-500' : 'border-slate-700/50'} text-white px-3 py-2 rounded-lg text-xs font-mono`} />
                                    {currentErrors['floatSeed'] && <span className="text-red-500 text-[10px] block mt-1">{currentErrors['floatSeed']}</span>}
                                </div>
                                {['logistic', 'tent'].includes(mode) && (
                                    <div>
