        let y = seedVal2 || 34221;
        let z = seedVal3 || 4321;
        let w = seedVal4 || 6969;

        // Sanitize to avoid 0 if needed (KISS components generally handle it but good practice)
        if (x===0 && y===0 && z===0 && w===0) x = 12345;

