                for (; kk < n - 1; kk++) {
                    const y = (mt[kk] & upperMask) | (mt[kk + 1] & lowerMask);
                    mt[kk] = mt[kk + (m - n)] ^ (y >>> 1) ^ ((y & 1) ? matrixA : 0);
                }
                const y = (mt[n - 1] & upperMask) | (mt[0] & lowerMask);
                mt[n - 1] = mt[m - 1] ^ (y >>> 1) ^ ((y & 1) ? matrixA : 0);
