       if (lfsr === 0) lfsr = 1; // Prevent 0 lock
       const tap = parseInt(hexTap || '1D', 16);
       for(let i=0; i<limit; i++) {
          result.push(lfsr);
          const lsb = lfsr & 1;
          lfsr >>= 1;
          if (lsb) lfsr ^= tap;
       }
    }
    else if (mode === 'lfsr' || mode === 'lfsr32') {
