  c?: string;
  m?: string;
  hexTap?: string;
  stringSeed?: string;
  floatSeed?: string;
  paramR?: string;
  paramA?: string;
  paramB?: string;
  paramC?: string;
  paramDt?: string;
  fibSeed1?: string;
  fibSeed2?: string;
  [key: string]: string | undefined;
}

export const generateLocalSequence = (mode: string, params: GeneratorParams, limit: number = 10): number[] => {
  const result: number[] = [];

  if (mode === 'mwc64x') {
       let state = BigInt(params.seed || 12345);
       for(let i=0; i<limit; i++) {
           const c = state >> 32n;
           const x = state & 0xFFFFFFFFn;
           state = x * 4294883355n + c;
           const out = Number(x ^ c);
           result.push(out);
       }
  }
  else if (mode === 'wichmann-hill') {
       let s1 = parseInt(params.seed || '100');
       let s2 = parseInt(params.seed2 || '200');
       let s3 = parseInt(params.seed3 || '300');

       for(let i=0; i<limit; i++) {
           s1 = (171 * s1) % 30269;
           s2 = (172 * s2) % 30307;
           s3 = (170 * s3) % 30323;

           let val = (s1/30269.0) + (s2/30307.0) + (s3/30323.0);
           val = val % 1.0;
           result.push(Number(val.toFixed(8)));
       }
  }
  else if (['lcg', 'nr', 'minstd', 'carbon', 'ggn', 'randu', 'zx81'].includes(mode)) {
      const m = BigInt(params.m || '4294967296');
      const a = BigInt(params.a || '1664525');
      const c = BigInt(params.c || '1013904223');
      let current = BigInt(params.seed || '12345');

      for(let i=0; i<limit; i++) {
          current = (a * current + c) % m;
          result.push(Number(current));
      }
  }
  else if (mode === 'fib') {
      let a = parseInt(params.fibSeed1 || '0');
      let b = parseInt(params.fibSeed2 || '1');
      result.push(a);
      result.push(b);
      for(let i=2; i<limit; i++) {
          const next = a + b;
          result.push(next);
          a = b;
          b = next;
      }
  }
  else {
      // Fallback for demo purposes
      for(let i=0; i<limit; i++) {
          result.push(Math.floor(Math.random() * 100));
      }
  }

  return result;
};

import React, { useState } from 'react';
import { generateLocalSequence, GeneratorParams } from '../utils/generatorUtils';

export interface FormParams extends GeneratorParams {}

const ALGORITHMS = [
  { id: 'lcg', name: 'LCG (Standard)' },
  { id: 'minstd', name: 'MINSTD (Lehmer)' },
  { id: 'mwc64x', name: 'MWC64X' },
  { id: 'wichmann-hill', name: 'Wichmann-Hill' },
  { id: 'randu', name: 'RANDU' },
  { id: 'zx81', name: 'ZX81' },
  { id: 'fib', name: 'Fibonacci' }
];

const Playground: React.FC = () => {
    const [selectedAlgo, setSelectedAlgo] = useState<string>('lcg');
    const [formParams, setFormParams] = useState<FormParams>({
        seed: '12345', a: '1664525', c: '1013904223', m: '4294967296'
    });
    const [sequence, setSequence] = useState<number[]>([]);

    const setDefaultParams = (id: string) => {
        let p: FormParams = {};

        switch (id) {
            case 'lcg': p.a='1664525'; p.c='1013904223'; p.m='4294967296'; p.seed='12345'; break;
            case 'randu': p.a='65539'; p.c='0'; p.m='2147483648'; p.seed='1'; break;
            case 'zx81': p.a='75'; p.c='74'; p.m='65537'; p.seed='1'; break;
            case 'nr': p.a='1664525'; p.c='1013904223'; p.m='4294967296'; p.seed='12345'; break;
            case 'minstd': p.a='16807'; p.c='0'; p.m='2147483647'; p.seed='12345'; break;
            case 'carbon': p.a='16807'; p.c='0'; p.m='2147483647'; p.seed='1'; break;
            case 'ggn': p.a='16807'; p.c='0'; p.m='2147483647'; p.seed='12345'; break;
            case 'mwc64x': p.seed='12345'; break;
            case 'wichmann-hill': p.seed='100'; p.seed2='200'; p.seed3='300'; break;

            case 'xorshift': p.seed='123456789'; break;
            case 'xoroshiro128plus': p.seed='123456'; p.seed2='987654'; break;
            case 'xorshift1024': p.seed='123456789'; break;
            case 'tausworthe': p.seed='123'; p.seed2='456'; p.seed3='789'; break;
            case 'lfsr8': p.seed='31'; p.hexTap='1D'; break;
            case 'lfsr': p.seed='12345'; p.hexTap='B400'; break;
            case 'lfsr32': p.seed='12345'; p.hexTap='80200003'; break;
            case 'lfsr64': p.stringSeed='12345'; p.hexTap='D800000000000000'; break;

            case 'mt19937': p.seed='5489'; break;
            case 'pcg32': p.seed='42'; p.seed2='54'; break;
            case 'sfc32': p.seed='123'; p.seed2='456'; p.seed3='789'; p.seed4='999'; break;
            case 'wyrand': p.seed='777'; break;
            case 'splitmix': p.seed='123456789'; break;
            case 'mulberry': p.seed='12345'; break;
            case 'kiss': p.seed='12345'; p.seed2='34221'; p.seed3='4321'; p.seed4='6969'; break;

            case 'logistic': p.floatSeed='0.5'; p.paramR='3.99'; break;
            case 'tent': p.floatSeed='0.5'; p.paramR='1.99'; break;
            case 'henon': p.floatSeed='0.1'; p.paramA='1.4'; p.paramB='0.3'; break;
            case 'ikeda': p.floatSeed='0.1'; p.paramA='0.9'; break;
            case 'lorenz': p.floatSeed='0.1'; p.paramA='10'; p.paramB='28'; p.paramC='2.66'; p.paramDt='0.01'; break;
            case 'rossler': p.floatSeed='0.1'; p.paramA='0.2'; p.paramB='0.2'; p.paramC='5.7'; p.paramDt='0.05'; break;

            case 'fib': p.fibSeed1='0'; p.fibSeed2='1'; break;
            case 'middle-square': p.seed='1234'; break;
            case 'lagged-fib': p.seed='12345'; p.a='7'; p.c='10'; break;
            case 'blum-blum-shub': p.seed='3'; p.m='209'; break;
        }
        setFormParams(p);
    };

    const handleGenerate = () => {
        const result = generateLocalSequence(selectedAlgo, formParams, 15);
        setSequence(result);
    };

    const handleAlgoChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const id = e.target.value;
        setSelectedAlgo(id);
        setDefaultParams(id);
    };

    const handleParamChange = (key: string, value: string) => {
        setFormParams(prev => ({ ...prev, [key]: value }));
    };

    return (
        <div className="glass-panel p-6 rounded-xl border-l-4 border-purple-500 shadow-lg">
            <div className="flex items-center mb-6">
                <svg className="w-6 h-6 mr-2 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z"></path></svg>
                <h2 className="text-xl font-bold text-white">Generator Laboratory</h2>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-1 space-y-4">
                    <div>
                        <label className="block text-xs font-mono text-slate-400 mb-1 uppercase tracking-wider">Algorithm</label>
                        <select 
                            value={selectedAlgo} 
                            onChange={handleAlgoChange}
                            className="w-full bg-slate-800 border border-slate-600 text-white p-2 rounded font-mono text-sm focus:border-purple-500 focus:outline-none"
                        >
                            {ALGORITHMS.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
                            <option value="nr">Numerical Recipes</option>
                            <option value="carbon">Carbon Lib</option>
                            <option value="ggn">GGN</option>
                        </select>
                    </div>

                    <div className="bg-slate-900/50 p-4 rounded border border-slate-800 space-y-3">
                         <h4 className="text-xs font-bold text-slate-500 uppercase mb-2">Parameters</h4>
                         {Object.keys(formParams).length > 0 ? (
                             Object.entries(formParams).map(([key, val]) => (
                                 <div key={key}>
                                     <label className="block text-[10px] font-mono text-purple-300 uppercase mb-1">{key}</label>
                                     <input 
                                         type="text" 
                                         value={val || ''} 
                                         onChange={(e) => handleParamChange(key, e.target.value)}
                                         className="w-full bg-slate-800 border border-slate-700 text-white px-2 py-1 rounded font-mono text-xs focus:border-purple-500 focus:outline-none"
                                     />
                                 </div>
                             ))
                         ) : (
                             <p className="text-xs text-slate-600 italic">No configurable parameters for this selection.</p>
                         )}
                    </div>

                    <button 
                        onClick={handleGenerate}
                        className="w-full bg-purple-600 hover:bg-purple-500 text-white font-bold py-2 px-4 rounded transition-all shadow-lg shadow-purple-900/20"
                    >
                        Generate Sequence
                    </button>
                </div>

                <div className="lg:col-span-2">
                    <div className="bg-slate-950 p-6 rounded-lg border border-slate-800 h-full flex flex-col">
                        <h3 className="text-xs font-bold text-slate-500 mb-4 uppercase flex justify-between">
                            <span>Output Stream</span>
                            <span className="text-slate-600">N=15</span>
                        </h3>
                        <div className="font-mono text-sm space-y-1 flex-1 overflow-y-auto max-h-[400px]">
                            {sequence.length > 0 ? (
                                sequence.map((n, i) => (
                                    <div key={i} className="flex gap-4 border-b border-slate-900 py-2 hover:bg-slate-900/30 transition-colors">
                                        <span className="text-slate-600 w-8 select-none text-right">{i}:</span>
                                        <span className="text-purple-300">{n}</span>
                                    </div>
                                ))
                            ) : (
                                <div className="h-full flex items-center justify-center text-slate-700 italic">
                                    Click generate to produce numbers...
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Playground;
